/* ──────────────────────────────────────────────────────────────────────────
 * 1b. DASHBOARD LIST SLOTS — optional overlay states (independent of template)
 * ────────────────────────────────────────────────────────────────────────── */
(function () {
  'use strict';

  function clearClones(ctn) {
    if (!ctn) return;
    ctn.querySelectorAll('[data-ms-clone="true"]').forEach(function (n) {
      n.parentNode.removeChild(n);
    });
  }

  function listSlots(ctn) {
    return {
      template: ctn.querySelector('[data-ms-code="list-template"]'),
      loading:  ctn.querySelector('[data-ms-code="list-loading"]'),
      empty:    ctn.querySelector('[data-ms-code="list-empty"]'),
      error:    ctn.querySelector('[data-ms-code="list-error"]')
    };
  }

  function reveal(el) {
    if (!el) return;
    el.style.removeProperty('display');
    // Clearing the inline style exposes whatever the stylesheet sets. If a
    // CSS class (e.g. `is-state`) still forces `display: none`, removing the
    // inline property isn't enough — set an explicit value to override it.
    // Authors can opt into a specific value via `data-ms-display`.
    if (getComputedStyle(el).display === 'none') {
      el.style.display = el.getAttribute('data-ms-display') || 'block';
    }
  }

  function conceal(el) {
    if (el) el.style.display = 'none';
  }

  /** Toggle list-loading | list-empty | list-error | ready — each node is optional. */
  function showListState(ctn, stateKey) {
    if (!ctn) return;
    var loading = ctn.querySelector('[data-ms-code="list-loading"]');
    var empty = ctn.querySelector('[data-ms-code="list-empty"]');
    var error = ctn.querySelector('[data-ms-code="list-error"]');
    if (loading) { if (stateKey === 'list-loading') reveal(loading); else conceal(loading); }
    if (empty)   { if (stateKey === 'list-empty')   reveal(empty);   else conceal(empty); }
    if (error)   { if (stateKey === 'list-error')   reveal(error);   else conceal(error); }
  }

  function hideTemplate(ctn) {
    var tpl = ctn && ctn.querySelector('[data-ms-code="list-template"]');
    if (tpl) tpl.style.display = 'none';
  }

  function showTemplate(ctn) {
    var tpl = ctn && ctn.querySelector('[data-ms-code="list-template"]');
    if (tpl) tpl.style.removeProperty('display');
  }

  function prepareNoData(ctn) {
    clearClones(ctn);
    hideTemplate(ctn);
  }

  window.DashboardListSlots = {
    clearClones: clearClones,
    listSlots: listSlots,
    showListState: showListState,
    hideTemplate: hideTemplate,
    showTemplate: showTemplate,
    prepareNoData: prepareNoData
  };
})();


/* ──────────────────────────────────────────────────────────────────────────
 * 1c. DASHBOARD COMMON — helpers shared by sections 2–5
 *     Exposes window.DashboardCommon. Must run before the section IIFEs.
 * ────────────────────────────────────────────────────────────────────────── */
(function () {
  'use strict';

  if (window.DashboardCommon) return;

  var ROOT_SELECTOR = '[data-ms-code="dashboard-page"]';

  /** Resolve a reference field to its record id (accepts an id string or {id}). */
  function idOf(ref) { return (ref && (ref.id || ref)) || null; }

  /** Linear lookup of a record by its id. */
  function byId(arr, id) {
    for (var i = 0; i < arr.length; i++) {
      if (arr[i].id === id) return arr[i];
    }
    return null;
  }

  /** Build an id → record map for O(1) lookups. */
  function indexById(records) {
    var idx = Object.create(null);
    (records || []).forEach(function (r) { if (r && r.id) idx[r.id] = r; });
    return idx;
  }

  /** Set textContent of the first matching node, skipping empty values. */
  function setText(root, selector, text) {
    if (text == null || text === '') return;
    var el = root.querySelector(selector);
    if (el) el.textContent = text;
  }

  /** Two-digit zero-padded number; em dash when null/undefined. */
  function pad2(n) {
    if (n == null) return '—';
    return ('0' + n).slice(-2);
  }

  /** Read a table-name override from the dashboard root, then body, then fallback. */
  function tableAttr(name, fallback) {
    var root = document.querySelector(ROOT_SELECTOR);
    return (root && root.getAttribute(name)) || document.body.getAttribute(name) || fallback;
  }

  /**
   * Lesson counts for one course:
   *  - total:     lessons in the course
   *  - completed: lessons with a completed progress row
   *  - started:   lessons with any progress row (opened or completed)
   */
  function courseStats(courseId, data) {
    var total = data.lessons.filter(function (l) {
      return idOf(l.data.course) === courseId;
    }).length;
    var courseProgress = data.progress.filter(function (p) {
      return idOf(p.data.course) === courseId;
    });
    var completed = courseProgress.filter(function (p) {
      return (p.data.completed | 0) === 1;
    }).length;
    return { completed: completed, total: total, started: courseProgress.length };
  }

  /**
   * Build loading/empty/error helpers around a section's container lookup.
   * `findContainer` is called fresh each time so DOM timing never matters.
   */
  function makeListState(findContainer) {
    function ui() { return window.DashboardListSlots; }
    return {
      showLoading: function () {
        var c = findContainer();
        if (c) ui().showListState(c, 'list-loading');
      },
      showEmpty: function () {
        var c = findContainer();
        if (!c) return;
        ui().prepareNoData(c);
        ui().showListState(c, 'list-empty');
      },
      showError: function () {
        var c = findContainer();
        if (!c) return;
        ui().prepareNoData(c);
        ui().showListState(c, 'list-error');
      }
    };
  }

  window.DashboardCommon = {
    ROOT_SELECTOR: ROOT_SELECTOR,
    idOf: idOf,
    byId: byId,
    indexById: indexById,
    setText: setText,
    pad2: pad2,
    tableAttr: tableAttr,
    courseStats: courseStats,
    makeListState: makeListState
  };
})();


/* ──────────────────────────────────────────────────────────────────────────
 * 2. DASHBOARD STATS — Lessons Done count, Day Streak, Lessons Total
 * ────────────────────────────────────────────────────────────────────────── */
(function () {
  'use strict';

  var C = window.DashboardCommon;

  var CONFIG = {
    STREAK_FIELDS: ['last_watched_at', 'completed_at'],
    STREAK_TARGET: '[data-ms-code="streak"]',
    LESSONS_TOTAL_TARGET: '[data-ms-code="lessons-total"]',
    COUNT_CONTAINER: '[data-ms-code="list-container"][ms-code-mode="count"]'
  };

  document.addEventListener('DOMContentLoaded', boot);

  async function boot() {
    // Only run on a page that actually has the dashboard stat targets.
    if (!document.querySelector(CONFIG.STREAK_TARGET + ',' + CONFIG.LESSONS_TOTAL_TARGET
      + ',' + CONFIG.COUNT_CONTAINER)) return;
    if (!window.$memberstackDom || !window.MSDataCache) return;
    var ms = window.$memberstackDom;
    var tableProgress = C.tableAttr('ms-code-table-progress', 'lesson_progress');
    var tableLesson = C.tableAttr('ms-code-table-lesson', 'lessons');
    try {
      var member = await window.MSDataCache.getMember(ms);
      if (!member) return;
      var loaded = await Promise.all([
        window.MSDataCache.load(ms, tableProgress, { owner: { equals: member.id } }),
        window.MSDataCache.load(ms, tableLesson, null)
      ]);
      var progress = loaded[0];
      var lessons = loaded[1];
      paintLessonsTotal(lessons.length);
      paintStreak(computeStreak(progress));
      paintCountStats(progress, member);
    } catch (err) {
      console.error('[dashboard-stats] boot failed', err);
    }
  }

  function paintLessonsTotal(n) {
    var el = document.querySelector(CONFIG.LESSONS_TOTAL_TARGET);
    if (el) el.textContent = String(n);
  }

  function paintStreak(n) {
    var el = document.querySelector(CONFIG.STREAK_TARGET);
    if (el) el.textContent = String(n);
  }

  /** Count consecutive days (back from today/yesterday) with at least one progress event. */
  function computeStreak(progress) {
    var DAY = 86400000, days = {};
    progress.forEach(function (r) {
      var ts = pickField(r, CONFIG.STREAK_FIELDS);
      if (!ts) return;
      var d = new Date(ts);
      if (isNaN(d.getTime())) return;
      d.setHours(0, 0, 0, 0);
      days[d.getTime()] = true;
    });
    var sorted = Object.keys(days).map(Number).sort(function (a, b) { return b - a; });
    if (!sorted.length) return 0;
    var today = new Date(); today.setHours(0, 0, 0, 0);
    var cursor = today.getTime();
    if (sorted[0] !== cursor && sorted[0] !== cursor - DAY) return 0;
    if (sorted[0] === cursor - DAY) cursor -= DAY;
    var streak = 0;
    for (var i = 0; i < sorted.length; i++) {
      if (sorted[i] === cursor) { streak++; cursor -= DAY; }
      else if (sorted[i] < cursor) break;
    }
    return streak;
  }

  /** Fill count-mode containers with a filtered tally of progress rows. */
  function paintCountStats(progress, member) {
    document.querySelectorAll(CONFIG.COUNT_CONTAINER).forEach(function (el) {
      if (el.getAttribute('ms-code-table') !== 'lesson_progress') return;
      var whereStr = el.getAttribute('ms-code-where') || '';
      var ownerField = el.getAttribute('ms-code-owner-field');
      var count = progress.filter(function (r) {
        if (ownerField && r.data && C.idOf(r.data[ownerField]) !== member.id) return false;
        if (!whereStr) return true;
        var parts = whereStr.split(':');
        var field = parts[0], value = parts.slice(1).join(':');
        var actual = r.data && r.data[field];
        return String(actual) === String(value) || Number(actual) === Number(value);
      }).length;
      var target = el.querySelector('[data-ms-code="count-value"]');
      if (target) target.textContent = String(count);
    });
  }

  /** First non-empty value among `fields` on record.data. */
  function pickField(record, fields) {
    if (!record || !record.data) return null;
    for (var i = 0; i < fields.length; i++) {
      if (record.data[fields[i]]) return record.data[fields[i]];
    }
    return null;
  }
})();


/* ──────────────────────────────────────────────────────────────────────────
 * 3. DASHBOARD CONTINUE CARD + NARRATIVE
 * ────────────────────────────────────────────────────────────────────────── */
(function () {
  'use strict';

  var C = window.DashboardCommon;
  var ui = window.DashboardListSlots;

  var CONFIG = {
    NARRATIVE_TARGET: '[data-ms-code="narrative"]',
    NARRATIVE_EMPTY: 'Pick a course to dive in.',
    NARRATIVE_FALLBACK: 'Pick up where you left off.',
    CONTINUE_QUERY: { table: 'lesson_progress', whereAttr: 'completed:0' }
  };

  var state = C.makeListState(findContainer);

  document.addEventListener('DOMContentLoaded', boot);

  async function boot() {
    if (!findContainer()) return; // not the dashboard page
    state.showLoading();
    if (!window.$memberstackDom || !window.MSDataCache) { state.showError(); return; }
    var ms = window.$memberstackDom;
    var tableProgress = C.tableAttr('ms-code-table-progress', 'lesson_progress');
    var tableLesson = C.tableAttr('ms-code-table-lesson', 'lessons');
    var tableModule = C.tableAttr('ms-code-table-module', 'modules');
    var tableCourse = C.tableAttr('ms-code-table-course', 'courses');
    CONFIG.CONTINUE_QUERY.table = tableProgress;
    try {
      var member = await window.MSDataCache.getMember(ms);
      if (!member) { state.showEmpty(); return; }
      var loaded = await Promise.all([
        window.MSDataCache.load(ms, tableProgress, { owner: { equals: member.id } }),
        window.MSDataCache.load(ms, tableLesson, null),
        window.MSDataCache.load(ms, tableModule, null),
        window.MSDataCache.load(ms, tableCourse, null)
      ]);
      var data = { progress: loaded[0], lessons: loaded[1], modules: loaded[2], courses: loaded[3] };
      paintNarrative(data);
      paintContinueCard(data);
    } catch (err) {
      console.error('[dashboard-continue] boot failed', err);
      state.showError();
    }
  }

  function paintNarrative(data) {
    var el = document.querySelector(CONFIG.NARRATIVE_TARGET);
    if (!el) return;
    var resume = pickResume(data);
    if (!resume) { el.textContent = CONFIG.NARRATIVE_EMPTY; return; }
    if (resume.course) {
      var stats = C.courseStats(resume.course.id, data);
      el.textContent = "You're " + stats.completed + ' lessons into '
        + resume.course.data.title + '. Pick up where you left off.';
    } else {
      el.textContent = CONFIG.NARRATIVE_FALLBACK;
    }
  }

  function paintContinueCard(data) {
    var ctn = findContainer();
    if (!ctn) return;
    var slots = ui.listSlots(ctn);
    var resume = pickResume(data);
    if (!resume || !slots.template) {
      ui.prepareNoData(ctn);
      ui.showListState(ctn, 'list-empty');
      return;
    }

    var lesson = resume.lesson, mod = resume.module, course = resume.course;
    var t = slots.template;

    C.setText(t, '[data-ms-field="lesson.title"]', lesson.data.title);
    C.setText(t, '[data-ms-code="continue-label"]',
      'COURSE ' + C.pad2(course && course.data.order) + ' · LESSON ' + C.pad2(lesson.data.order));
    C.setText(t, '[data-ms-code="module-path"]',
      [course && course.data.title, mod && ('Module ' + (mod.data.order || '') + ': ' + mod.data.title)]
        .filter(Boolean).join(' · '));

    var watched = Number((resume.progressRow && resume.progressRow.data.watched_seconds) || 0);
    var total = Number(lesson.data.duration_minutes || 0) * 60;
    C.setText(t, '[data-ms-code="continue-time-remaining"]', formatRemaining(Math.max(0, total - watched)));

    if (mod) {
      var modLessons = data.lessons.filter(function (l) { return C.idOf(l.data.module) === mod.id; });
      var done = modLessons.filter(function (l) {
        return data.progress.some(function (p) {
          return C.idOf(p.data.lesson) === l.id && (p.data.completed | 0) === 1;
        });
      }).length;
      C.setText(t, '[data-ms-code="module-progress-label"]', done + ' / ' + modLessons.length + ' LESSONS');
      var fill = t.querySelector('[data-ms-code="module-progress-fill"]');
      if (fill) fill.style.width = (modLessons.length ? Math.round(done / modLessons.length * 100) : 0) + '%';
    }

    setDetailLinks(t, { lesson: lesson.id, course: course ? course.id : null });
    ui.showTemplate(ctn);
    ui.showListState(ctn, 'ready');
  }

  /** Recency of a progress row — newest of last_watched_at / completed_at. */
  function progressTime(p) {
    var d = p.data || {};
    return new Date(d.last_watched_at || d.completed_at || 0).getTime();
  }

  /** Resolve the course a progress row belongs to (denormalized, or via lesson). */
  function courseIdOfProgress(p, data) {
    var direct = C.idOf(p.data.course);
    if (direct) return direct;
    var lesson = C.byId(data.lessons, C.idOf(p.data.lesson));
    return lesson && C.idOf(lesson.data.course);
  }

  /**
   * The lesson to resume: walk the member's courses newest-activity-first and
   * return the first one that still has an unfinished lesson — the first lesson
   * (module order, then lesson order) without a completed progress row.
   * Returns { lesson, course, module, progressRow } or null.
   */
  function pickResume(data) {
    if (!data.progress.length) return null;

    // Set of lessons with a completed row.
    var completed = Object.create(null);
    data.progress.forEach(function (p) {
      if ((p.data.completed | 0) === 1) completed[C.idOf(p.data.lesson)] = true;
    });

    // Module → order, for course-wide lesson sequencing.
    var modOrder = Object.create(null);
    data.modules.forEach(function (m) { modOrder[m.id] = m.data.order || 0; });

    // Candidate courses, ordered by most recent progress activity.
    var seen = Object.create(null), courseIds = [];
    data.progress.slice()
      .sort(function (a, b) { return progressTime(b) - progressTime(a); })
      .forEach(function (p) {
        var cid = courseIdOfProgress(p, data);
        if (cid && !seen[cid]) { seen[cid] = true; courseIds.push(cid); }
      });

    for (var i = 0; i < courseIds.length; i++) {
      var courseId = courseIds[i];
      var lesson = data.lessons
        .filter(function (l) { return C.idOf(l.data.course) === courseId; })
        .sort(function (a, b) {
          var byMod = (modOrder[C.idOf(a.data.module)] || 0) - (modOrder[C.idOf(b.data.module)] || 0);
          return byMod !== 0 ? byMod : (a.data.order || 0) - (b.data.order || 0);
        })
        .filter(function (l) { return !completed[l.id]; })[0];
      if (!lesson) continue; // course fully complete — try the next one

      return {
        lesson: lesson,
        course: C.byId(data.courses, courseId),
        module: C.byId(data.modules, C.idOf(lesson.data.module)),
        progressRow: data.progress.filter(function (p) {
          return C.idOf(p.data.lesson) === lesson.id;
        })[0] || null
      };
    }
    return null; // every touched course is finished
  }

  function setDetailLinks(root, ids) {
    root.querySelectorAll('[data-ms-code="detail-link"]').forEach(function (a) {
      var page = a.getAttribute('ms-code-detail-page') || '';
      var param = a.getAttribute('ms-code-id-param') || 'id';
      var key = a.getAttribute('data-ms-field') || '';
      var id = key === 'lesson.id' ? ids.lesson
            : key === 'course.id' ? ids.course
            : key === 'id' ? (ids.lesson || ids.course) : null;
      if (id) a.setAttribute('href', page + '?' + param + '=' + id);
    });
  }

  /** The continue card lives in the list-container matching table + where attrs. */
  function findContainer() {
    var nodes = document.querySelectorAll(
      '[data-ms-code="list-container"][ms-code-table="' + CONFIG.CONTINUE_QUERY.table + '"]');
    for (var i = 0; i < nodes.length; i++) {
      if (nodes[i].getAttribute('ms-code-where') === CONFIG.CONTINUE_QUERY.whereAttr) return nodes[i];
    }
    return null;
  }

  function formatRemaining(sec) {
    if (!sec) return 'Just starting';
    var m = Math.floor(sec / 60), s = Math.floor(sec % 60);
    return m + ':' + ('0' + s).slice(-2) + ' remaining';
  }
})();


/* ──────────────────────────────────────────────────────────────────────────
 * 4. DASHBOARD COURSE GRID — variant-pattern course progress cards
 * ────────────────────────────────────────────────────────────────────────── */
(function () {
  'use strict';

  var C = window.DashboardCommon;
  var ui = window.DashboardListSlots;

  var CONFIG = {
    HOURS_FALLBACK: '~6 hours',
    STATUS_VALUES: ['complete', 'in_progress', 'not_started']
  };

  var state = C.makeListState(findContainer);

  document.addEventListener('DOMContentLoaded', boot);

  async function boot() {
    if (!findContainer()) return; // not the dashboard page
    state.showLoading();
    if (!window.$memberstackDom || !window.MSDataCache) { state.showError(); return; }
    var ms = window.$memberstackDom;
    var tableCourse = C.tableAttr('ms-code-table-course', 'courses');
    var tableLesson = C.tableAttr('ms-code-table-lesson', 'lessons');
    var tableProgress = C.tableAttr('ms-code-table-progress', 'lesson_progress');
    try {
      var member = await window.MSDataCache.getMember(ms);
      if (!member) { state.showEmpty(); return; }
      var loaded = await Promise.all([
        window.MSDataCache.load(ms, tableCourse, null),
        window.MSDataCache.load(ms, tableLesson, null),
        window.MSDataCache.load(ms, tableProgress, { owner: { equals: member.id } })
      ]);
      paintCourseGrid({ courses: loaded[0], lessons: loaded[1], progress: loaded[2] });
    } catch (err) {
      console.error('[dashboard-courses] boot failed', err);
      state.showError();
    }
  }

  function paintCourseGrid(data) {
    var ctn = findContainer();
    if (!ctn) return;
    var slots = ui.listSlots(ctn);
    if (!data.courses.length) {
      ui.prepareNoData(ctn);
      ui.showListState(ctn, 'list-empty');
      return;
    }
    if (!slots.template) return;

    var rows = data.courses.slice().sort(function (a, b) {
      return (a.data.order || 0) - (b.data.order || 0);
    });
    var per = parseInt(ctn.getAttribute('ms-code-per-page') || '0', 10);
    if (per > 0) rows = rows.slice(0, per);

    ui.clearClones(ctn);
    ui.hideTemplate(ctn);
    rows.forEach(function (course) {
      var card = slots.template.cloneNode(true);
      card.removeAttribute('data-ms-code');
      card.setAttribute('data-ms-clone', 'true');
      card.style.removeProperty('display');
      paintCourseCard(card, course, data);
      slots.template.parentNode.insertBefore(card, slots.template);
    });
    ui.showListState(ctn, 'ready');
  }

  function paintCourseCard(card, course, data) {
    var category = (course.data.category || '').toLowerCase();
    var stats = C.courseStats(course.id, data);
    var status = resolveStatus(stats);
    var pct = stats.total ? Math.round(stats.completed / stats.total * 100) : 0;
    var totalLessons = stats.total || course.data.lesson_count || 0;

    card.setAttribute('data-category', category);
    card.setAttribute('data-status', status);

    C.setText(card, '[data-ms-field="title"]', course.data.title);
    C.setText(card, '[data-ms-field="description"]', course.data.description);
    C.setText(card, '[data-ms-field="category"]', course.data.category);

    toggleVariants(card, 'category', category);
    toggleVariants(card, 'status', status);

    C.setText(card, '[data-ms-code="course-lessons-count"]', String(stats.completed));
    C.setText(card, '[data-ms-code="course-lessons-total"]', String(totalLessons));
    C.setText(card, '[data-ms-code="course-lessons-label"]',
      stats.completed + ' / ' + totalLessons + ' LESSONS');

    var pctEl = card.querySelector('[data-ms-code="course-progress-percent"], [data-ms-code="course-progress-text"]');
    if (pctEl) {
      pctEl.textContent = status === 'not_started'
        ? (course.data.hours_estimate || CONFIG.HOURS_FALLBACK)
        : pct + '%';
    }
    C.setText(card, '[data-ms-code="course-hours"]', course.data.hours_estimate || CONFIG.HOURS_FALLBACK);

    var fill = card.querySelector('[data-ms-code="course-progress-fill"]');
    if (fill) fill.style.width = pct + '%';

    // CTA label — "Get started" if untouched, "Continue" if in-progress,
    // "Re-watch" if complete.
    var ctaLabel = card.querySelector('[data-ms-code="course-cta-label"]');
    if (ctaLabel) {
      ctaLabel.textContent = status === 'complete' ? 'Re-watch'
        : status === 'in_progress' ? 'Continue'
        : 'Get started';
    }

    setDetailLinks(card, course.id);
  }

  /** Show only the variant nodes whose data-ms-show-value matches the active value. */
  function toggleVariants(root, attr, activeValue) {
    root.querySelectorAll('[data-ms-show-if="' + attr + '"]').forEach(function (n) {
      var v = n.getAttribute('data-ms-show-value');
      n.style.display = (v === activeValue) ? '' : 'none';
    });
  }

  function setDetailLinks(card, courseId) {
    card.querySelectorAll('[data-ms-code="detail-link"]').forEach(function (a) {
      var page = a.getAttribute('ms-code-detail-page') || '';
      var param = a.getAttribute('ms-code-id-param') || 'id';
      if (!page || !courseId) return;
      a.setAttribute('href', page + '?' + param + '=' + courseId);
    });
  }

  function resolveStatus(stats) {
    if (stats.total > 0 && stats.completed >= stats.total) return 'complete';
    if (stats.completed > 0 || stats.started > 0) return 'in_progress';
    return 'not_started';
  }

  function findContainer() {
    var tableCourse = C.tableAttr('ms-code-table-course', 'courses');
    return document.querySelector(
      '[data-ms-code="list-container"][ms-code-table="' + tableCourse + '"]');
  }
})();


/* ──────────────────────────────────────────────────────────────────────────
 * 5. DASHBOARD ACTIVITY — recent activity feed with synthesized meta + links
 * ────────────────────────────────────────────────────────────────────────── */
(function () {
  'use strict';

  var C = window.DashboardCommon;
  var ui = window.DashboardListSlots;

  var CONFIG = {
    DEFAULT_PER_PAGE: 5,
    META_FIELD_FALLBACKS: ['meta_text', 'message', 'description'],
    DATE_FIELD_FALLBACKS: ['created_at', 'createdAt', 'timestamp'],

    // Used when `meta_text` is empty on the row. {lesson} is replaced
    // by the joined lesson title; {actor} by activity.actor_name.
    TYPE_LABELS: {
      lesson_complete:  'Completed: {lesson}',
      course_complete:  'Completed a course',
      lesson_saved:     'Saved: {lesson}',
      course_saved:     'Saved a course',
      streak_milestone: 'Reached a new streak'
    },
    DEFAULT_LABEL: 'Activity'
  };

  var state = C.makeListState(findContainer);

  document.addEventListener('DOMContentLoaded', boot);

  async function boot() {
    if (!findContainer()) return; // not the dashboard page
    state.showLoading();
    if (!window.$memberstackDom || !window.MSDataCache) { state.showError(); return; }
    var ms = window.$memberstackDom;
    var tableActivity = C.tableAttr('ms-code-table-activity', 'activity');
    var tableLesson = C.tableAttr('ms-code-table-lesson', 'lessons');
    try {
      var member = await window.MSDataCache.getMember(ms);
      if (!member) { state.showEmpty(); return; }
      var loaded = await Promise.all([
        window.MSDataCache.load(ms, tableActivity, { owner: { equals: member.id } }),
        window.MSDataCache.load(ms, tableLesson, null)
      ]);
      paintActivityList(loaded[0], C.indexById(loaded[1]));
    } catch (err) {
      console.error('[dashboard-activity] boot failed', err);
      state.showError();
    }
  }

  function paintActivityList(rows, lessonsById) {
    var ctn = findContainer();
    if (!ctn) return;
    var slots = ui.listSlots(ctn);

    var sorted = rows.slice().sort(function (a, b) {
      return dateValue(b) - dateValue(a);
    });
    var per = parseInt(ctn.getAttribute('ms-code-per-page') || CONFIG.DEFAULT_PER_PAGE, 10);
    if (per > 0) sorted = sorted.slice(0, per);

    if (!sorted.length) {
      ui.prepareNoData(ctn);
      ui.showListState(ctn, 'list-empty');
      return;
    }
    if (!slots.template) return;

    ui.clearClones(ctn);
    ui.hideTemplate(ctn);
    sorted.forEach(function (row) {
      var node = slots.template.cloneNode(true);
      node.removeAttribute('data-ms-code');
      node.setAttribute('data-ms-clone', 'true');
      node.style.removeProperty('display');
      paintActivityRow(node, row, lessonsById);
      slots.template.parentNode.insertBefore(node, slots.template);
    });
    ui.showListState(ctn, 'ready');
  }

  function paintActivityRow(node, row, lessonsById) {
    var typeVal = row.data && row.data.type;
    if (typeVal) node.setAttribute('data-type', typeVal);
    node.querySelectorAll('[data-ms-show-if="type"]').forEach(function (icon) {
      icon.style.display = icon.getAttribute('data-ms-show-value') === typeVal ? '' : 'none';
    });

    var lessonId = row.data && C.idOf(row.data.lesson);
    var lesson = lessonId ? lessonsById[lessonId] : null;

    var meta = pickField(row, CONFIG.META_FIELD_FALLBACKS) || synthesizeMeta(row, lesson);
    C.setText(node, '[data-ms-field="meta_text"]', meta);
    C.setText(node, '[data-ms-code="activity-meta"]', meta);

    var dateRaw = pickField(row, CONFIG.DATE_FIELD_FALLBACKS);
    if (dateRaw) {
      var d = new Date(dateRaw);
      if (!isNaN(d.getTime())) {
        var rel = relativeTime(d);
        C.setText(node, '[data-ms-field="created_at"]', rel);
        C.setText(node, '[data-ms-code="activity-time"]', rel);
      }
    }

    if (node.tagName === 'A') {
      var href = pickField(row, ['link_url']) || synthesizeHref(typeVal, lesson, node);
      if (href) node.setAttribute('href', href);
    }
  }

  /** Fill {lesson}/{actor} placeholders in the type label when meta_text is absent. */
  function synthesizeMeta(row, lesson) {
    var typeVal = row.data && row.data.type;
    var template = CONFIG.TYPE_LABELS[typeVal] || CONFIG.DEFAULT_LABEL;
    return template
      .replace('{lesson}', (lesson && lesson.data && lesson.data.title) || 'a lesson')
      .replace('{actor}', (row.data && row.data.actor_name) || 'Member');
  }

  /** Build a lesson detail href for lesson-scoped activity types. */
  function synthesizeHref(typeVal, lesson, node) {
    if (!lesson || !lesson.id) return null;
    if (typeVal === 'lesson_complete' || typeVal === 'lesson_saved') {
      var page = node && node.getAttribute('ms-code-detail-page');
      var param = (node && node.getAttribute('ms-code-id-param')) || 'id';
      if (!page) return null;
      return page + '?' + param + '=' + lesson.id;
    }
    return null;
  }

  function dateValue(row) {
    return new Date(pickField(row, CONFIG.DATE_FIELD_FALLBACKS) || 0);
  }

  /** First non-empty value among `fields`, checking record.data then the record top level. */
  function pickField(record, fields) {
    if (!record) return null;
    for (var i = 0; i < fields.length; i++) {
      var key = fields[i];
      var fromData = record.data && record.data[key];
      if (fromData != null && fromData !== '') return fromData;
      var fromTop = record[key];
      if (fromTop != null && fromTop !== '') return fromTop;
    }
    return null;
  }

  function findContainer() {
    var tableActivity = C.tableAttr('ms-code-table-activity', 'activity');
    return document.querySelector(
      '[data-ms-code="list-container"][ms-code-table="' + tableActivity + '"]');
  }

  function relativeTime(d) {
    var s = Math.floor((Date.now() - d.getTime()) / 1000);
    if (s < 60) return 'JUST NOW';
    var m = Math.floor(s / 60); if (m < 60) return m + ' MIN AGO';
    var h = Math.floor(m / 60); if (h < 24) return h + ' HOUR' + (h === 1 ? '' : 'S') + ' AGO';
    var dd = Math.floor(h / 24);
    if (dd === 1) return 'YESTERDAY';
    if (dd < 7) return dd + ' DAYS AGO';
    var w = Math.floor(dd / 7); if (w < 5) return w + ' WEEK' + (w === 1 ? '' : 'S') + ' AGO';
    var mo = Math.floor(dd / 30); if (mo < 12) return mo + ' MONTH' + (mo === 1 ? '' : 'S') + ' AGO';
    return Math.floor(dd / 365) + ' YEAR+ AGO';
  }
})();

/* ===================== course-detail.js ===================== */
(function () {
  'use strict';

  var LABEL = '[course-detail]';
  var DEBUG = /[?&]debug\b/.test(window.location.search);
  var MONTHS = ['JAN', 'FEB', 'MAR', 'APR', 'MAY', 'JUN', 'JUL', 'AUG', 'SEP', 'OCT', 'NOV', 'DEC'];
  var FEATURES = {
    // Data sections (table-backed)
    INSTRUCTOR: true,
    OUTCOMES: true,
    FIRST_LESSON: true,
    // Writes
    ENROLLMENT_WRITES: true
  };
  var TABLES = null;

  // Entry point: wait for DOM, then fetch + paint everything.
  document.addEventListener('DOMContentLoaded', function () { boot(); });

  async function boot() {
    // Root scope for all selectors so this script stays page-local.
    var root = document.querySelector('[data-ms-code="course-page"]');
    if (!root) return;

    showStateAll(root, 'list-loading');

    if (!window.$memberstackDom || !window.MSDataCache) {
      console.warn(LABEL + ' missing $memberstackDom or MSDataCache');
      showStateAll(root, 'list-error');
      return;
    }

    var ms = window.$memberstackDom;
    TABLES = tableConfig(root);
    var idParam = root.getAttribute('ms-code-id-param') || 'id';
    var slugParam = root.getAttribute('ms-code-slug-param') || 'slug';
    var courseId = getUrlParam(idParam);
    var courseSlug = getUrlParam(slugParam);

    if (!courseId && !courseSlug) {
      console.warn(LABEL + ' no ?' + idParam + ' or ?' + slugParam + ' in URL');
      showStateAll(root, 'list-error');
      return;
    }

    try {
      // Pull member once, then scope owner-only tables to this member.
      var member = await window.MSDataCache.getMember(ms);
      var memberId = member ? member.id : null;
      var ownerWhere = memberId ? { owner: { equals: memberId } } : null;

      var loaded = await Promise.all([
        window.MSDataCache.load(ms, TABLES.course, null),
        window.MSDataCache.load(ms, TABLES.module, null),
        window.MSDataCache.load(ms, TABLES.lesson, null),
        FEATURES.INSTRUCTOR ? window.MSDataCache.load(ms, TABLES.instructor, null) : Promise.resolve([]),
        FEATURES.OUTCOMES ? window.MSDataCache.load(ms, TABLES.outcome, null) : Promise.resolve([]),
        ownerWhere ? window.MSDataCache.load(ms, TABLES.progress, ownerWhere) : Promise.resolve([]),
        ownerWhere ? window.MSDataCache.load(ms, TABLES.enrollment, ownerWhere)     : Promise.resolve([]),
        ownerWhere ? window.MSDataCache.load(ms, TABLES.savedCourses, ownerWhere)   : Promise.resolve([])
      ]);

      var data = {
        courses: loaded[0], modules: loaded[1], lessons: loaded[2],
        instructors: loaded[3], outcomes: loaded[4],
        progress: loaded[5], enrollments: loaded[6], savedCourses: loaded[7]
      };

      if (DEBUG) console.log(LABEL + ' loaded', {
        courses: data.courses.length, modules: data.modules.length,
        lessons: data.lessons.length, instructors: data.instructors.length,
        outcomes: data.outcomes.length,
        progress: data.progress.length, enrollments: data.enrollments.length,
        saved_courses: data.savedCourses.length
      });

      var course = findCourse(data.courses, courseId, courseSlug);
      if (!course) {
        console.warn(LABEL + ' course not found for id="' + courseId + '" slug="' + courseSlug + '"');
        showStateAll(root, 'list-empty');
        return;
      }

      render(root, course, data, ms);
    } catch (err) {
      console.error(LABEL + ' boot failed', err);
      showStateAll(root, 'list-error');
    }
  }

  function render(root, course, data, ms) {
    var courseId = course.id;
    // Shape data into course-local slices once; painters stay dumb/simple.
    var modules = data.modules.filter(function (m) { return idOf(m.data.course) === courseId; }).sort(byOrder);
    var lessons = data.lessons.filter(function (l) { return idOf(l.data.course) === courseId; }).sort(byModuleThenOrder(modules));
    var progress = data.progress.filter(function (p) { return idOf(p.data.course) === courseId; });
    var enrollment = data.enrollments.find(function (e) { return idOf(e.data.course) === courseId; }) || null;
    var savedCourse = (data.savedCourses || []).find(function (s) { return idOf(s.data.course) === courseId; }) || null;
    var instructor = findInstructor(data.instructors, courseId);
    var outcomes = (data.outcomes || []).filter(function (o) { return idOf(o.data.course) === courseId; }).sort(byOrder);

    hideModals(root);
    // Paint read-only UI blocks first...
    paintHero(root, course, modules, lessons, progress, enrollment);
    paintCurriculum(root, modules, lessons, progress);
    if (FEATURES.OUTCOMES) paintOutcomes(root, outcomes);
    else hideSection(root, 'outcomes');
    if (FEATURES.FIRST_LESSON) paintFirstLesson(root, modules, lessons);
    else hideSection(root, 'first-lesson');
    if (FEATURES.INSTRUCTOR) paintInstructor(root, instructor);
    else hideSection(root, 'instructor');
    // ...then attach writes/actions after state is on screen.
    if (FEATURES.ENROLLMENT_WRITES) wireEnrollment(root, course, enrollment, savedCourse, lessons, progress, ms);
    else hideEnrollmentButtons(root);
    hideAllStates(root);
  }

  // ============= HERO =============

  function paintHero(root, course, modules, lessons, progress, enrollment) {
    fillField(root, 'course.title', course.data.title);
    fillField(root, 'course.description', course.data.description);
    fillField(root, 'course.category', course.data.category);
    fillField(root, 'course.lesson_count', course.data.lesson_count || lessons.length);
    fillField(root, 'course.hours_estimate', course.data.hours_estimate);
    fillField(root, 'course.order', course.data.order);
    fillField(root, 'course.cover_image', course.data.cover_image);

    setTokenText(root, 'modules-count', String(modules.length));
    setTokenText(root, 'updated-at', formatMonthYear(course.updatedAt || course.createdAt));

    var completed = progress.filter(function (p) { return (p.data.completed | 0) === 1; }).length;
    var total = course.data.lesson_count || lessons.length;
    var hours = course.data.hours_estimate || '';
    var pct = total > 0 ? Math.round(completed / total * 100) : 0;

    setTokenText(root, 'progress-count', String(completed));

    var fillEl = queryToken(root, 'progress-fill');
    if (fillEl) fillEl.style.width = pct + '%';

    // Computed labels — single elements, no surrounding text. Use these in
    // Webflow whenever you'd otherwise have whitespace between two spans.
    setLabel(root, 'hero-eyebrow', pad2(course.data.order) + ' / ' + (course.data.category || '').toUpperCase()
      + ' · ' + total + ' LESSONS · ' + (hours || '').toUpperCase());
    setLabel(root, 'stats-lessons', total + ' LESSONS');
    setLabel(root, 'stats-modules', modules.length + ' MODULES');
    setLabel(root, 'stats-hours', (hours || '').toUpperCase());
    setLabel(root, 'stats-updated', course.updatedAt || course.createdAt
      ? 'UPDATED ' + formatMonthYear(course.updatedAt || course.createdAt) : '');
    setLabel(root, 'curriculum-summary', total + ' lessons · ' + modules.length + ' modules');
    setLabel(root, 'progress-fraction', completed + ' / ' + total);

    var enrollState = resolveEnrollState(enrollment);
    // Variant toggles drive mutually exclusive UI states in Webflow.
    toggleVariants(root, 'enroll', enrollState);
    toggleVariants(root, 'cta', resolveCtaMode(enrollState, completed, progress.length));

    setLabel(root, 'enroll-active-label', "You're enrolled · " + completed + ' of ' + total + ' lessons complete');
    setLabel(root, 'enroll-paused-label', 'Paused · ' + completed + ' of ' + total + ' lessons complete');
    setLabel(root, 'enroll-dropped-label', 'You dropped this course · re-enroll any time');
    setLabel(root, 'enroll-completed-label', 'Course complete · all ' + total + ' lessons done');
    setLabel(root, 'enroll-none-label', 'Free with your membership');

    var resumeLesson = resolveResumeLesson(enrollment, lessons, progress);
    if (resumeLesson) {
      setTokenText(root, 'resume-order', pad2(resumeLesson.data.order));
      setLabel(root, 'resume-cta-label', 'Continue · Lesson ' + pad2(resumeLesson.data.order));
      setDetailLink(root.querySelector('[data-ms-code="detail-link"][data-ms-show-value="resume"]'), resumeLesson.id);
    }

    var firstLesson = lessons[0];
    if (firstLesson) {
      setDetailLink(root.querySelector('[data-ms-code="detail-link"][data-ms-show-value="start"]'), firstLesson.id);
      setDetailLink(queryToken(root, 'watch-first'), firstLesson.id);
    }

    if (course.data.cover_image) paintCover(root, course.data.cover_image);
  }

  // Cover painter (attribute-only):
  // - Use explicit token roles:
  //     [data-ms-code="cover-bg"]  for background-image containers
  //     [data-ms-code="cover-img"] for <img> tags
  // - Wrapper token: [data-ms-code="cover"].
  function paintCover(root, url) {
    var bgNodes = queryTokenAll(root, 'cover-bg');
    var imgNodes = queryTokenAll(root, 'cover-img');

    if (bgNodes.length || imgNodes.length) {
      bgNodes.forEach(function (el) { el.style.backgroundImage = 'url("' + url + '")'; });
      imgNodes.forEach(function (el) {
        if (el.tagName === 'IMG') el.setAttribute('src', url);
      });
      return;
    }

    queryTokenAll(root, 'cover').forEach(function (el) {
      if (el.tagName === 'IMG') {
        el.setAttribute('src', url);
        return;
      }
      if (el.querySelector('img[data-ms-code="cover"]')) return;
      el.style.backgroundImage = 'url("' + url + '")';
    });
  }

  function resolveEnrollState(enrollment) {
    if (!enrollment) return 'none';
    // Defensive default keeps legacy/unknown statuses from breaking UI.
    var s = (enrollment.data.status || 'active').toLowerCase();
    return ['active', 'paused', 'dropped', 'completed'].indexOf(s) !== -1 ? s : 'active';
  }

  function resolveCtaMode(enrollState, completed, started) {
    if (enrollState === 'none') return 'enroll';
    if (enrollState === 'paused' || enrollState === 'dropped') return 'reactivate';
    if (enrollState === 'completed') return 'resume';
    // Resume once any lesson has been opened or completed; otherwise Start.
    return (completed > 0 || started > 0) ? 'resume' : 'start';
  }

  function resolveResumeLesson(enrollment, lessons, progress) {
    // Build the completed-lesson set so we never resume to a finished lesson.
    var completedIds = Object.create(null);
    progress.forEach(function (p) {
      if ((p.data.completed | 0) === 1) completedIds[idOf(p.data.lesson)] = true;
    });

    // Priority 1: explicit current_lesson on enrollment — but only if it's
    // not already completed. Stale enrolment pointers (e.g. set at enrol time
    // and never updated) used to keep the CTA stuck on "Lesson 01".
    if (enrollment) {
      var ids = arrayOfIds(enrollment.data.current_lesson);
      for (var i = 0; i < ids.length; i++) {
        if (completedIds[ids[i]]) continue;
        var hit = lessons.find(function (l) { return l.id === ids[i]; });
        if (hit) return hit;
      }
    }
    // Priority 2: most recently touched incomplete progress row.
    var sorted = progress.slice().sort(function (a, b) {
      return tsOf(b.data.last_watched_at || b.data.completed_at) - tsOf(a.data.last_watched_at || a.data.completed_at);
    });
    for (var j = 0; j < sorted.length; j++) {
      if ((sorted[j].data.completed | 0) === 1) continue;
      var lid = idOf(sorted[j].data.lesson);
      var lesson = lessons.find(function (l) { return l.id === lid; });
      if (lesson) return lesson;
    }
    // Priority 3: first lesson the member hasn't completed yet (lessons here
    // are already ordered by module → lesson).
    for (var k = 0; k < lessons.length; k++) {
      if (!completedIds[lessons[k].id]) return lessons[k];
    }
    // All lessons completed → resume points at the last one for "Re-watch".
    return lessons[lessons.length - 1] || null;
  }

  // ============= CURRICULUM =============

  function paintCurriculum(root, modules, lessons, progress) {
    var ctn = root.querySelector('[data-ms-code="curriculum"]');
    if (!ctn) return;
    var moduleTpl = ctn.querySelector('[data-ms-code="module-template"]');
    if (!moduleTpl) return;

    clearClones(ctn);
    moduleTpl.style.display = 'none';

    if (!modules.length) { showState(ctn, 'list-empty'); return; }

    var resumeLessonId = pickResumeLessonId(lessons, progress);

    modules.forEach(function (mod) {
      var modClone = moduleTpl.cloneNode(true);
      modClone.removeAttribute('data-ms-code');
      modClone.setAttribute('data-ms-clone', 'true');
      modClone.style.display = '';

      fillField(modClone, 'module.title', mod.data.title);
      fillField(modClone, 'module.lesson_count', mod.data.lesson_count || 0);
      fillField(modClone, 'module.order', mod.data.order);
      setLabel(modClone, 'module-meta',
        'MODULE ' + pad2(mod.data.order) + ' · ' + (mod.data.lesson_count || 0) + ' LESSONS');
      // Optional module-level navigation:
      // - if the module wrapper itself is a link, wire it
      // - or wire any explicit module-link token nodes inside
      if (modClone.tagName === 'A') setDetailLink(modClone, mod.id);
      queryTokenAll(modClone, 'module-link').forEach(function (el) {
        setDetailLink(el, mod.id);
      });

      var innerLessonTpl = modClone.querySelector('[data-ms-code="lesson-template"]');
      if (innerLessonTpl) {
        // Remove template from clone, then append concrete lesson rows.
        var anchor = innerLessonTpl.parentNode;
        anchor.removeChild(innerLessonTpl);
        var modLessons = lessons.filter(function (l) { return idOf(l.data.module) === mod.id; });
        var unlockedIndex = firstIncompleteIndex(modLessons, progress);
        modLessons.forEach(function (lesson) {
          var row = innerLessonTpl.cloneNode(true);
          row.removeAttribute('data-ms-code');
          row.setAttribute('data-ms-clone', 'true');
          row.style.display = '';
          paintLessonRow(row, lesson, progress, resumeLessonId, modLessons, unlockedIndex);
          anchor.appendChild(row);
        });
      }

      moduleTpl.parentNode.insertBefore(modClone, moduleTpl);
    });
  }

  function paintLessonRow(row, lesson, progress, resumeLessonId, modLessons, unlockedIndex) {
    var minutes = lesson.data.duration_minutes || 0;
    fillField(row, 'lesson.title', lesson.data.title);
    fillField(row, 'lesson.duration_minutes', minutes);
    fillField(row, 'lesson.order', lesson.data.order);

    setLabel(row, 'lesson-duration-done', minutes + ' min');
    setLabel(row, 'lesson-duration-active', 'CONTINUE · ' + minutes + ' MIN');
    setLabel(row, 'lesson-duration-todo', minutes + ' min');

    var status = resolveLessonStatus(lesson, progress, resumeLessonId, modLessons, unlockedIndex);
    // If markup has no explicit locked variant, degrade to todo so row stays visible.
    if (status === 'locked' && !hasVariant(row, 'status', 'locked')) status = 'todo';

    toggleVariants(row, 'status', status);
    if (status === 'locked') {
      row.removeAttribute('href');
      row.setAttribute('aria-disabled', 'true');
    } else {
      row.removeAttribute('aria-disabled');
      setDetailLink(row, lesson.id);
    }
  }

  function pickResumeLessonId(lessons, progress) {
    var sorted = progress.slice().sort(function (a, b) {
      return tsOf(b.data.last_watched_at) - tsOf(a.data.last_watched_at);
    });
    for (var i = 0; i < sorted.length; i++) {
      if ((sorted[i].data.completed | 0) !== 1) return idOf(sorted[i].data.lesson);
    }
    return null;
  }

  function resolveLessonStatus(lesson, progress, resumeLessonId, modLessons, unlockedIndex) {
    // done > active > locked > todo precedence
    var prog = progress.find(function (p) { return idOf(p.data.lesson) === lesson.id; });
    if (prog && (prog.data.completed | 0) === 1) return 'done';
    if (modLessons && modLessons.length) {
      var idx = modLessons.findIndex(function (l) { return l.id === lesson.id; });
      if (unlockedIndex !== -1 && idx > unlockedIndex) return 'locked';
      if (idx === unlockedIndex) return 'active';
    }
    if (lesson.id === resumeLessonId || prog) return 'active';
    return 'todo';
  }

  function firstIncompleteIndex(lessons, progress) {
    for (var i = 0; i < lessons.length; i++) {
      var lessonId = lessons[i] && lessons[i].id;
      var rec = progress.find(function (p) { return idOf(p.data.lesson) === lessonId; });
      if (!(rec && (rec.data.completed | 0) === 1)) return i;
    }
    return -1;
  }

  function hasVariant(scope, attr, value) {
    return !!scope.querySelector('[data-ms-show-if="' + attr + '"][data-ms-show-value="' + value + '"]');
  }

  // ============= FIRST LESSON PREVIEW =============

  function paintFirstLesson(root, modules, lessons) {
    var section = root.querySelector('[data-ms-code="first-lesson"]');
    if (!section) return;
    var lesson = lessons[0];
    if (!lesson) return;
    var mod = modules.find(function (m) { return m.id === idOf(lesson.data.module); });
    var minutes = lesson.data.duration_minutes || 0;

    fillField(section, 'first-lesson.title', lesson.data.title);
    fillField(section, 'first-lesson.description', lesson.data.description);
    fillField(section, 'first-lesson.duration_minutes', minutes);
    fillField(section, 'first-lesson.order', lesson.data.order);
    fillField(section, 'first-lesson.video_url', lesson.data.video_url);
    if (mod) fillField(section, 'first-module.order', mod.data.order);

    setLabel(section, 'first-lesson-duration', minutes + ' MIN');
    setLabel(section, 'first-lesson-meta',
      'LESSON ' + pad2(lesson.data.order) + ' · MODULE ' + pad2(mod ? mod.data.order : 1));

    section.querySelectorAll('[data-ms-code="detail-link"]').forEach(function (a) {
      setDetailLink(a, lesson.id);
    });

    // Preview thumb fallback:
    // If lesson.video_url is YouTube/Vimeo, derive a public thumbnail URL and
    // paint it on elements marked with the preview-thumb token.
    var thumbCandidates = deriveVideoThumbnailCandidates(lesson.data.video_url);
    if (thumbCandidates.length) {
      var thumbNodes = queryTokenAll(section, 'preview-thumb');
      thumbNodes.forEach(function (el) {
        if (el.tagName === 'IMG') {
          // For <img>, try high-res first then downgrade on load failure.
          setImgWithFallback(el, thumbCandidates);
        }
        else {
          // CSS backgrounds cannot reliably detect 404; use best candidate.
          el.style.backgroundImage = 'url("' + thumbCandidates[0] + '")';
          el.style.backgroundSize = 'cover';
          el.style.backgroundPosition = 'center';
        }
      });
    }
  }

  function deriveVideoThumbnailCandidates(videoUrl) {
    if (!videoUrl || typeof videoUrl !== 'string') return [];
    var parsed;
    try { parsed = new URL(videoUrl); } catch (e) { return []; }
    var host = (parsed.hostname || '').toLowerCase();

    // YouTube:
    // - youtube.com/watch?v=VIDEO_ID
    // - youtu.be/VIDEO_ID
    // - youtube.com/embed/VIDEO_ID
    if (host.indexOf('youtube.com') !== -1 || host.indexOf('youtu.be') !== -1) {
      var ytId = youtubeIdFromUrl(parsed);
      if (!ytId) return [];
      // Prefer high-res first, then degrade gracefully.
      return [
        'https://i.ytimg.com/vi_webp/' + ytId + '/maxresdefault.webp',
        'https://i.ytimg.com/vi/' + ytId + '/maxresdefault.jpg',
        'https://i.ytimg.com/vi/' + ytId + '/sddefault.jpg',
        'https://img.youtube.com/vi/' + ytId + '/hqdefault.jpg'
      ];
    }

    // Vimeo:
    // - vimeo.com/12345678
    // - player.vimeo.com/video/12345678
    // Preferred thumbnail endpoint requires no auth in many cases.
    if (host.indexOf('vimeo.com') !== -1) {
      var vmId = vimeoIdFromUrl(parsed);
      if (!vmId) return [];
      // Vumbnail variants: prefer large first.
      return [
        'https://vumbnail.com/' + vmId + '_large.jpg',
        'https://vumbnail.com/' + vmId + '.jpg',
        'https://vumbnail.com/' + vmId + '_medium.jpg'
      ];
    }

    return [];
  }

  function setImgWithFallback(img, urls) {
    if (!img || !urls || !urls.length) return;
    var i = 0;
    function tryNext() {
      if (i >= urls.length) return;
      img.setAttribute('src', urls[i++]);
    }
    img.onerror = function () { tryNext(); };
    tryNext();
  }

  function youtubeIdFromUrl(u) {
    if (!u) return null;
    var host = (u.hostname || '').toLowerCase();
    if (host.indexOf('youtu.be') !== -1) {
      var shortId = (u.pathname || '').replace(/^\/+/, '').split('/')[0];
      return shortId || null;
    }
    var v = u.searchParams.get('v');
    if (v) return v;
    var parts = (u.pathname || '').split('/').filter(Boolean);
    var embedIdx = parts.indexOf('embed');
    if (embedIdx !== -1 && parts[embedIdx + 1]) return parts[embedIdx + 1];
    return null;
  }

  function vimeoIdFromUrl(u) {
    if (!u) return null;
    var parts = (u.pathname || '').split('/').filter(Boolean);
    for (var i = parts.length - 1; i >= 0; i--) {
      if (/^\d+$/.test(parts[i])) return parts[i];
    }
    return null;
  }

  // ============= OUTCOMES =============
  // Renders cards from the `outcomes` table, scoped to this course and
  // sorted by `order`. Mark one card as the template with
  // [data-ms-code="outcome-template"]; inside it use:
  //   [data-ms-field="outcome.title"]       → h3 / heading
  //   [data-ms-field="outcome.description"] → p / subhead
  //   [data-ms-code="outcome-label"]        → "OUTCOME 01" tagline
  // Wrap the grid in [data-ms-code="outcomes"] so the whole section can
  // hide itself when no outcomes exist.

  function paintOutcomes(root, outcomes) {
    var section = root.querySelector('[data-ms-code="outcomes"]');
    var tpl = (section || root).querySelector('[data-ms-code="outcome-template"]');
    if (!tpl) return;
    var anchor = tpl.parentNode;

    anchor.querySelectorAll('[data-ms-clone="true"][data-ms-code="outcome-card"]')
      .forEach(function (n) { n.parentNode.removeChild(n); });
    tpl.style.display = 'none';

    if (!outcomes.length) {
      if (section) section.style.display = 'none';
      return;
    }
    if (section) section.style.display = '';

    outcomes.forEach(function (o, i) {
      var card = tpl.cloneNode(true);
      card.removeAttribute('data-ms-code');
      card.setAttribute('data-ms-clone', 'true');
      card.setAttribute('data-ms-code', 'outcome-card');
      card.style.display = '';

      fillField(card, 'outcome.title', o.data.title);
      fillField(card, 'outcome.description', o.data.description);
      fillField(card, 'outcome.order', o.data.order);

      setLabel(card, 'outcome-label', 'OUTCOME ' + pad2(o.data.order || (i + 1)));

      anchor.insertBefore(card, tpl);
    });
  }

  // ============= INSTRUCTOR =============

  function findInstructor(instructors, courseId) {
    var match = instructors.find(function (i) {
      return arrayOfIds(i.data.courses).indexOf(courseId) !== -1;
    });
    if (match) return match;
    if (DEBUG) {
      if (instructors.length) {
        console.warn(LABEL + ' no instructor matched courseId=' + courseId
          + ' — first instructor.courses raw value:', instructors[0].data.courses,
          '| parsed ids:', arrayOfIds(instructors[0].data.courses));
      } else {
        console.warn(LABEL + ' instructors table is empty');
      }
    }
    return null;
  }

  function paintInstructor(root, instructor) {
    var section = root.querySelector('[data-ms-code="instructor"]');
    if (!section) return;
    if (!instructor) { section.style.display = 'none'; return; }
    section.style.display = '';

    fillField(section, 'instructor.name', instructor.data.name);
    fillField(section, 'instructor.title', instructor.data.title);
    fillField(section, 'instructor.bio', instructor.data.bio);
    fillField(section, 'instructor.years_of_experience', instructor.data.years_of_experience);

    if (instructor.data.avatar) paintAvatar(section, instructor.data.avatar);
  }

  function paintAvatar(section, url) {
    var nodes = section.querySelectorAll('[data-ms-field="instructor.avatar"]');
    nodes.forEach(function (el) {
      if (el.tagName === 'IMG') {
        el.setAttribute('src', url);
      } else {
        el.style.backgroundImage = 'url("' + url + '")';
        el.style.backgroundSize = 'cover';
        el.style.backgroundPosition = 'center';
        el.textContent = '';
      }
    });
  }

  // ============= ENROLLMENT WRITES =============

  function wireEnrollment(root, course, enrollment, savedCourse, lessons, progress, ms) {
    var enrollBtn = queryToken(root, 'enroll-btn');
    var reactivateBtn = queryToken(root, 'reactivate-btn');
    var dropBtn = queryToken(root, 'drop');
    var resetBtn = queryToken(root, 'hard-unenroll');
    var saveCourseBtns = queryTokenAll(root, 'save-course');

    // Visibility — drop only makes sense when there's an active/paused
    // enrollment to drop. Hard-unenroll is available whenever there's
    // anything to wipe (enrollment row OR any saved progress).
    var status = enrollment && enrollment.data && enrollment.data.status;
    var canDrop = status === 'active' || status === 'paused';
    var canReset = !!enrollment || (progress && progress.length > 0);
    if (dropBtn)  dropBtn.style.display  = canDrop  ? '' : 'none';
    if (resetBtn) resetBtn.style.display = canReset ? '' : 'none';

    paintSaveCourseState(root, !!savedCourse);

    if (enrollBtn) enrollBtn.addEventListener('click', function (e) {
      e.preventDefault(); enrollAction(ms, course, enrollment);
    });
    if (reactivateBtn) reactivateBtn.addEventListener('click', function (e) {
      e.preventDefault(); setStatus(ms, enrollment, 'active');
    });
    if (dropBtn) dropBtn.addEventListener('click', function (e) {
      e.preventDefault();
      if (!enrollment) return;
      openConfirm(root, 'drop-modal',
        'Drop this course? Your progress is kept and you can re-enroll any time.',
        function () { setStatus(ms, enrollment, 'dropped'); });
    });
    if (resetBtn) resetBtn.addEventListener('click', function (e) {
      e.preventDefault();
      openConfirm(root, 'reset-modal',
        'Reset this course? This deletes your enrollment, lesson progress, saved lessons, saved courses, and activity for this course. This cannot be undone.',
        function () { hardUnenroll(ms, course, enrollment, lessons, progress); });
    });
    saveCourseBtns.forEach(function (saveCourseBtn) {
      saveCourseBtn.addEventListener('click', function (e) {
        e.preventDefault();
        toggleSaveCourse(ms, course, savedCourse);
      });
    });
  }

  function paintSaveCourseState(root, saved) {
    // UI text/icon styling should come from Webflow state variants.
    // Script only flips state; it does not mutate button text.
    toggleVariants(root, 'save-course', saved ? 'saved' : 'unsaved');
  }

  async function toggleSaveCourse(ms, course, existing) {
    try {
      var member = await window.MSDataCache.getMember(ms);
      if (!member) return;
      if (existing) {
        var existingId = recordId(existing);
        if (existingId) {
          await writeWithRetry(function () {
            return ms.deleteDataRecord({ recordId: existingId });
          }, 'save-course');
        }
      } else {
        await writeWithRetry(function () {
          return ms.createDataRecord({
            table: TABLES.savedCourses,
            data: { owner: member.id, course: course.id, saved_at: new Date().toISOString() }
          });
        }, 'save-course');
      }
      window.MSDataCache.invalidate(TABLES.savedCourses);
      window.location.reload();
    } catch (err) {
      console.error(LABEL + ' toggle save course failed', err);
    }
  }

  async function enrollAction(ms, course, existing) {
    try {
      // If a row already exists (paused/dropped), reuse it by reactivating.
      if (existing) { await setStatus(ms, existing, 'active'); return; }
      var member = await window.MSDataCache.getMember(ms);
      if (!member) return;
      await writeWithRetry(function () {
        return ms.createDataRecord({
          table: TABLES.enrollment,
          data: { owner: member.id, course: course.id, enrolled_at: new Date().toISOString(), status: 'active' }
        });
      }, 'enroll');
      window.MSDataCache.invalidate(TABLES.enrollment);
      window.location.reload();
    } catch (err) { console.error(LABEL + ' enroll failed', err); }
  }

  async function setStatus(ms, enrollment, status) {
    if (!enrollment) return;
    var id = recordId(enrollment);
    if (!id) { console.error(LABEL + ' setStatus: enrollment has no id, aborting', enrollment); return; }
    try {
      // Memberstack expects `recordId`, not `id`, on update/delete APIs.
      await writeWithRetry(function () {
        return ms.updateDataRecord({ recordId: id, data: { status: status } });
      }, 'enrollment-status');
      window.MSDataCache.invalidate(TABLES.enrollment);
      window.location.reload();
    } catch (err) { console.error(LABEL + ' update enrollment failed', err); }
  }

  // Hard unenroll: deletes enrollment + lesson_progress + saved_courses +
  // saved_lessons + activity rows that belong to this course.
  async function hardUnenroll(ms, course, enrollment, lessons, progress) {
    try {
      var member = await window.MSDataCache.getMember(ms);
      if (!member) return;
      var courseId = course.id;
      var lessonIds = lessons.map(function (l) { return l.id; });
      var ownerWhere = { owner: { equals: member.id } };

      // Auxiliary cleanup tables (saved_*, activity) are best-effort: if one
      // isn't provisioned in this Memberstack project the query 404s. Swallow
      // that per-table so a missing table can't block the core reset
      // (enrollment + lesson_progress deletes).
      function loadOrEmpty(table) {
        return window.MSDataCache.load(ms, table, ownerWhere).catch(function (err) {
          console.warn(LABEL + ' hard unenroll: skipping "' + table + '" cleanup — '
            + ((err && (err.status || err.message)) || 'load failed'));
          return [];
        });
      }

      var ownedRows = await Promise.all([
        loadOrEmpty(TABLES.savedCourses),
        loadOrEmpty(TABLES.savedLessons),
        loadOrEmpty(TABLES.activity)
      ]);
      var savedCourses = ownedRows[0].filter(function (s) { return idOf(s.data && s.data.course) === courseId; });
      var savedLessons = ownedRows[1].filter(function (s) { return lessonIds.indexOf(idOf(s.data && s.data.lesson)) !== -1; });
      var activityRows = ownedRows[2].filter(function (a) { return lessonIds.indexOf(idOf(a.data && a.data.lesson)) !== -1; });

      // Build thunks (not in-flight promises) so the shared queue can
      // retry any individual delete that gets rate-limited. Skip any
      // record that's missing an id rather than firing /undefined.
      // Memberstack's deleteDataRecord infers the table from recordId.
      var jobs = [];
      function del(rec) {
        var id = recordId(rec);
        if (!id) return;
        jobs.push(function () { return ms.deleteDataRecord({ recordId: id }); });
      }

      if (enrollment) del(enrollment);
      progress.forEach(del);
      savedCourses.forEach(del);
      savedLessons.forEach(del);
      activityRows.forEach(del);

      if (DEBUG) console.log(LABEL + ' hard unenroll deleting', {
        enrollments: enrollment ? 1 : 0, lesson_progress: progress.length,
        saved_courses: savedCourses.length, saved_lessons: savedLessons.length,
        activity: activityRows.length, total: jobs.length
      });

      // Bounded concurrency + per-job 429 backoff. Default 4 in flight.
      var outcome = await window.MSDataCache.runWrites(jobs, { label: 'hard-unenroll' });

      [TABLES.enrollment, TABLES.progress, TABLES.savedCourses, TABLES.savedLessons, TABLES.activity].forEach(function (t) {
        window.MSDataCache.invalidate(t);
      });

      if (outcome.failures > 0) {
        console.error(LABEL + ' hard unenroll: ' + outcome.failures + ' of ' + jobs.length
          + ' deletes failed after retries — reloading anyway, retry the button to clean up the rest');
      }
      window.location.reload();
    } catch (err) { console.error(LABEL + ' hard unenroll failed', err); }
  }

  // ============= CONFIRM MODAL =============
  // Looks for [data-ms-code="<key>"] inside root (e.g. drop-modal, reset-modal).
  // Inside that scope, [data-ms-code="confirm-yes"] runs the action,
  // [data-ms-code="confirm-cancel"] (or [data-ms-code="confirm-backdrop"]) closes.
  // Falls back to native confirm() when no modal element is present.
  function openConfirm(root, key, fallbackMessage, onConfirm) {
    var modal = queryToken(root, key);
    if (!modal) {
      if (window.confirm(fallbackMessage)) onConfirm();
      return;
    }

    var yes = queryToken(modal, 'confirm-yes');
    var cancel = queryToken(modal, 'confirm-cancel');
    var backdrop = queryToken(modal, 'confirm-backdrop');

    function close() {
      modal.style.display = 'none';
      if (yes) yes.removeEventListener('click', onYes);
      if (cancel) cancel.removeEventListener('click', onNo);
      if (backdrop) backdrop.removeEventListener('click', onNo);
      document.removeEventListener('keydown', onKey);
    }
    function onYes(e) { e.preventDefault(); close(); onConfirm(); }
    function onNo(e)  { e.preventDefault(); close(); }
    // Escape-to-close keeps parity with normal modal UX.
    function onKey(e) { if (e.key === 'Escape') onNo(e); }

    if (yes)     yes.addEventListener('click', onYes);
    if (cancel)  cancel.addEventListener('click', onNo);
    if (backdrop) backdrop.addEventListener('click', onNo);
    document.addEventListener('keydown', onKey);

    // Use a real value (not '') so we override any CSS rule that hides
    // the modal by default (e.g. .modal_wrapper { display: none }).
    // Honor a per-modal override if you need block/grid:
    //   <div data-ms-code="drop-modal" data-modal-display="block">
    var openAs = modal.getAttribute('data-modal-display') || 'flex';
    modal.style.display = openAs;
  }

  // Make sure both modals start hidden, regardless of how Webflow rendered
  // them. Belt-and-suspenders for sites that don't add display:none in CSS.
  function hideModals(root) {
    queryTokenAll(root, 'drop-modal').concat(queryTokenAll(root, 'reset-modal'))
      .forEach(function (m) { m.style.display = 'none'; });
  }

  // ============= HELPERS =============

  function findCourse(courses, id, slug) {
    if (id) {
      var byId = courses.find(function (c) { return c.id === id; });
      if (byId) return byId;
    }
    if (slug) {
      var bySlug = courses.find(function (c) { return c.data && c.data.slug === slug; });
      if (bySlug) return bySlug;
    }
    return null;
  }

  function fillField(root, key, value) {
    if (value == null || value === '') return;
    root.querySelectorAll('[data-ms-field="' + key + '"]').forEach(function (el) {
      var flag = el.getAttribute('data-ms-code');
      // Same field key can render as text, padded number, image src, or bg-image.
      if (flag === 'bg-image')      el.style.backgroundImage = 'url("' + value + '")';
      else if (el.tagName === 'IMG') el.setAttribute('src', value);
      else if (flag === 'pad')       el.textContent = pad2(value);
      else                            el.textContent = value;
    });
  }

  function setLabel(root, key, value) {
    if (value == null) return;
    queryTokenAll(root, key).forEach(function (el) {
      el.textContent = value;
    });
  }

  function setText(root, sel, text) {
    if (text == null) return;
    var el = root.querySelector(sel);
    if (el) el.textContent = text;
  }

  function setEachText(root, sel, text) {
    if (text == null) return;
    root.querySelectorAll(sel).forEach(function (el) { el.textContent = text; });
  }

  function setTokenText(root, key, text) {
    if (text == null) return;
    queryTokenAll(root, key).forEach(function (el) { el.textContent = text; });
  }

  function toggleVariants(root, attr, activeValue) {
    // Declarative variant system:
    // keep only nodes whose [data-ms-show-value] matches activeValue.
    root.querySelectorAll('[data-ms-show-if="' + attr + '"]').forEach(function (n) {
      n.style.display = (n.getAttribute('data-ms-show-value') === String(activeValue)) ? '' : 'none';
    });
  }

  function setDetailLink(el, recordId) {
    if (!el || !recordId) return;
    var page = el.getAttribute('ms-code-detail-page');
    if (!page) return;
    var param = el.getAttribute('ms-code-id-param') || 'id';
    el.setAttribute('href', page + '?' + param + '=' + recordId);
  }

  function clearClones(root) {
    root.querySelectorAll('[data-ms-clone="true"]').forEach(function (n) { n.parentNode.removeChild(n); });
  }


  function getUrlParam(name) {
    try { return new URL(window.location.href).searchParams.get(name); } catch (e) { return null; }
  }

  function idOf(ref) {
    // Normalize Memberstack REFERENCE values from many possible shapes.
    if (!ref) return null;
    if (typeof ref === 'string') return ref;
    if (Array.isArray(ref)) return idOf(ref[0]);
    if (typeof ref === 'object') return ref.id || ref._id || null;
    return null;
  }

  // Pull the record id off whatever wrapper Memberstack returned.
  // Different projects have surfaced this as id, _id, or recordId.
  function recordId(r) {
    if (!r) return null;
    var id = r.id || r._id || r.recordId;
    if (!id) {
      console.warn(LABEL + ' could not find id on record — keys:', Object.keys(r), r);
    }
    return id || null;
  }

  // Run a single write through MSDataCache.runWrites so it inherits 429
  // backoff + retry. Falls back to a plain call if runWrites is unavailable.
  function writeWithRetry(thunk, label) {
    if (window.MSDataCache && typeof window.MSDataCache.runWrites === 'function') {
      return window.MSDataCache.runWrites([thunk], { label: label, stopOnError: true })
        .then(function (o) { return o.results[0]; });
    }
    return Promise.resolve().then(thunk);
  }

  // Permissive — accepts arrays, comma-separated strings, single ids,
  // single objects, and {ids:[…]} / {records:[…]} wrappers. This matches
  // every shape we've seen Memberstack return for REFERENCE_MANY fields.
  function arrayOfIds(refs) {
    if (!refs) return [];
    if (Array.isArray(refs)) return refs.map(idOf).filter(Boolean);
    if (typeof refs === 'string') {
      return refs.split(',').map(function (s) { return s.trim(); }).filter(Boolean);
    }
    if (typeof refs === 'object') {
      if (Array.isArray(refs.ids)) return refs.ids;
      if (Array.isArray(refs.records)) return refs.records.map(idOf).filter(Boolean);
      var single = idOf(refs);
      return single ? [single] : [];
    }
    return [];
  }

  function byOrder(a, b) { return (a.data.order || 0) - (b.data.order || 0); }

  function byModuleThenOrder(modules) {
    // Stable lesson ordering: module.order first, then lesson.order.
    var map = {};
    modules.forEach(function (m, i) { map[m.id] = (m.data.order != null ? m.data.order : i); });
    return function (a, b) {
      var ma = map[idOf(a.data.module)] || 0;
      var mb = map[idOf(b.data.module)] || 0;
      if (ma !== mb) return ma - mb;
      return (a.data.order || 0) - (b.data.order || 0);
    };
  }

  function pad2(n) {
    var x = parseInt(n, 10);
    if (isNaN(x)) return String(n == null ? '' : n);
    return x < 10 ? '0' + x : String(x);
  }

  function formatMonthYear(dateStr) {
    if (!dateStr) return '';
    var d = new Date(dateStr);
    if (isNaN(d.getTime())) return '';
    return MONTHS[d.getMonth()] + ' ' + d.getFullYear();
  }

  function tsOf(dateStr) {
    if (!dateStr) return 0;
    var t = new Date(dateStr).getTime();
    return isNaN(t) ? 0 : t;
  }

  // ============= STATE SLOTS =============

  function showState(scope, key) {
    ['list-loading', 'list-empty', 'list-error'].forEach(function (k) {
      var el = scope.querySelector('[data-ms-code="' + k + '"]');
      if (el) el.style.display = (k === key ? '' : 'none');
    });
  }

  function showStateAll(root, key) {
    // Keep state messaging scoped to curriculum block for now.
    var s = root.querySelector('[data-ms-code="curriculum"]');
    if (s) showState(s, key);
  }

  function hideAllStates(root) {
    root.querySelectorAll('[data-ms-code="list-loading"], [data-ms-code="list-empty"], [data-ms-code="list-error"]')
      .forEach(function (el) { el.style.display = 'none'; });
  }

  function hideSection(root, code) {
    var el = root.querySelector('[data-ms-code="' + code + '"]');
    if (el) el.style.display = 'none';
  }

  function hideEnrollmentButtons(root) {
    root.querySelectorAll(tokenSelector('drop') + ','
      + tokenSelector('hard-unenroll') + ','
      + tokenSelector('enroll-btn') + ','
      + tokenSelector('reactivate-btn') + ','
      + tokenSelector('save-course'))
      .forEach(function (el) { el.style.display = 'none'; });
  }

  function tableConfig(root) {
    return {
      course: root.getAttribute('ms-code-table-course') || 'courses',
      module: root.getAttribute('ms-code-table-module') || 'modules',
      lesson: root.getAttribute('ms-code-table-lesson') || 'lessons',
      instructor: root.getAttribute('ms-code-table-instructor') || 'instructors',
      outcome: root.getAttribute('ms-code-table-outcome') || 'outcomes',
      progress: root.getAttribute('ms-code-table-progress') || 'lesson_progress',
      enrollment: root.getAttribute('ms-code-table-enrollment') || 'enrollments',
      savedCourses: root.getAttribute('ms-code-table-saved-courses') || 'saved_courses',
      savedLessons: root.getAttribute('ms-code-table-saved-lessons') || 'saved_lessons',
      activity: root.getAttribute('ms-code-table-activity') || 'activity'
    };
  }

  function tokenSelector(key) {
    return '[data-ms-code="' + key + '"]';
  }

  function queryToken(scope, key) {
    return scope ? scope.querySelector(tokenSelector(key)) : null;
  }

  function queryTokenAll(scope, key) {
    return scope ? Array.prototype.slice.call(scope.querySelectorAll(tokenSelector(key))) : [];
  }
})();

/* ===================== lesson-detail.js ===================== */
(function () {
  'use strict';

  var LABEL = '[lesson-detail]';
  // Player sizing fallback for embed-style containers
  // ([data-ms-code="video-player"] on a non-iframe node).
  // Preferred: control size in Webflow/CSS; this is a safety net.
  var VIDEO_PLAYER_MIN_HEIGHT = 'auto';

  // On lesson open, re-stamp last_watched_at at most once per this window,
  // so revisiting a lesson doesn't write to the API on every page load.
  var LAST_WATCHED_TOUCH_MS = 5 * 60 * 1000;

  document.addEventListener('DOMContentLoaded', function () { boot(); });

  async function boot() {
    var root = document.querySelector('[data-ms-code="lesson-page"]');
    if (!root) return;

    if (!window.$memberstackDom || !window.MSDataCache) {
      console.warn(LABEL + ' missing $memberstackDom or MSDataCache');
      return;
    }

    var ms = window.$memberstackDom;
    var TABLES = tableConfig(root);
    var idParam = root.getAttribute('ms-code-id-param') || 'id';
    var slugParam = root.getAttribute('ms-code-slug-param') || 'slug';
    var lessonId = getUrlParam(idParam);
    var lessonSlug = getUrlParam(slugParam);
    if (!lessonId && !lessonSlug) return;

    try {
      var member = await window.MSDataCache.getMember(ms);
      var ownerWhere = member ? { owner: { equals: member.id } } : null;

      var loaded = await Promise.all([
        mustLoad(ms, TABLES.course, null),
        mustLoad(ms, TABLES.module, null),
        mustLoad(ms, TABLES.lesson, null),
        safeLoad(ms, TABLES.breakdown, null),
        safeLoad(ms, TABLES.reference, null),
        ownerWhere ? mustLoad(ms, TABLES.progress, ownerWhere) : Promise.resolve([]),
        ownerWhere ? safeLoad(ms, TABLES.savedLessons, ownerWhere) : Promise.resolve([]),
        ownerWhere ? safeLoad(ms, TABLES.enrollment, ownerWhere) : Promise.resolve([])
      ]);

      var data = {
        courses: loaded[0],
        modules: loaded[1],
        lessons: loaded[2],
        breakdown: loaded[3],
        references: loaded[4],
        progress: loaded[5],
        savedLessons: loaded[6],
        enrollments: loaded[7],
        tables: TABLES,
        member: member,
        ms: ms
      };

      var lesson = findLesson(data.lessons, lessonId, lessonSlug);
      if (!lesson) return;

      render(root, lesson, data);
    } catch (err) {
      console.error(LABEL + ' boot failed', err);
    }
  }

  async function mustLoad(ms, table, where) {
    return window.MSDataCache.load(ms, table, where);
  }

  async function safeLoad(ms, table, where) {
    try {
      return await window.MSDataCache.load(ms, table, where);
    } catch (err) {
      var code = err && err.code;
      if (code === 'data-table-not-found') {
        console.warn(LABEL + ' optional table missing: ' + table + ' (continuing)');
        return [];
      }
      throw err;
    }
  }

  function render(root, lesson, data) {
    var moduleId = idOf(lesson.data.module);
    var courseId = idOf(lesson.data.course);

    var mod = data.modules.find(function (m) { return recordId(m) === moduleId; }) || null;
    var course = data.courses.find(function (c) { return recordId(c) === courseId; }) || null;

    var moduleLessons = data.lessons
      .filter(function (l) { return idOf(l.data.module) === moduleId; })
      .sort(byOrder);

    var progress = data.progress.filter(function (p) { return idOf(p.data.course) === courseId; });
    var moduleProgress = progress.filter(function (p) { return idOf(p.data.lesson) && moduleLessons.some(function (l) { return recordId(l) === idOf(p.data.lesson); }); });

    paintBreadcrumbs(root, lesson, mod, course);
    paintHero(root, lesson, mod, moduleLessons, moduleProgress);
    paintVideo(root, lesson);
    paintBreakdown(root, lesson, data.breakdown);
    paintResources(root, lesson, data.references);
    paintLessonPagination(root, lesson, moduleLessons, data);
    paintSidebarCurriculum(root, lesson, mod, moduleLessons, moduleProgress);
    wireMarkComplete(root, lesson, data.member, data.ms, data.progress, data.tables, data.enrollments);
    wireSaveActions(root, lesson, course, data.member, data.ms, data.savedLessons, data.tables);
    wireViewCourse(root, course);

    // Fire-and-forget: log that the member opened this lesson.
    recordLessonOpen(lesson, data.member, data.ms, data.progress, data.tables);
  }

  function paintBreadcrumbs(root, lesson, mod, course) {
    var learn = queryToken(root, 'crumb-learn');
    var c = queryToken(root, 'crumb-course');
    var m = queryToken(root, 'crumb-module');
    var l = queryToken(root, 'crumb-lesson');

    if (learn && !learn.getAttribute('href')) console.warn(LABEL + ' set href on crumb-learn in markup');
    if (c && course) setDetailLink(c, recordId(course));
    if (m && mod) setDetailLink(m, recordId(mod));
    if (l) setDetailLink(l, recordId(lesson));

    fillField(root, 'course.title', course && course.data.title);
    fillField(root, 'module.title', mod && mod.data.title);
    fillField(root, 'lesson.title', lesson.data.title);
  }

  function paintHero(root, lesson, mod, moduleLessons, moduleProgress) {
    var idx = moduleLessons.findIndex(function (l) { return recordId(l) === recordId(lesson); });
    var total = moduleLessons.length || (mod && mod.data.lesson_count) || 0;
    var done = moduleLessons.filter(function (l) { return isDone(recordId(l), moduleProgress); }).length;
    var pct = total > 0 ? Math.round(done / total * 100) : 0;
    var mins = parseInt(lesson.data.duration_minutes || 0, 10) || 0;

    fillField(root, 'lesson.title', lesson.data.title);
    fillField(root, 'lesson.description', lesson.data.description);
    fillField(root, 'lesson.duration_minutes', mins);
    fillField(root, 'lesson.order', lesson.data.order);
    fillField(root, 'module.title', mod && mod.data.title);
    fillField(root, 'module.order', mod && mod.data.order);
    fillField(root, 'module.lesson_count', total);

    setLabel(root, 'lesson-meta',
      'LESSON ' + pad2((idx + 1) || lesson.data.order) + ' OF ' + pad2(total) + ' · ' + mins + ' MIN');
    setLabel(root, 'module-progress-label', done + ' / ' + total + ' Lessons');
    // Progress fraction markup reused on lesson pages.
    queryTokenAll(root, 'progress-count').forEach(function (el) { el.textContent = String(done); });
    root.querySelectorAll('[data-ms-code="curriculum"] [data-ms-field="course.lesson_count"],[data-ms-code="curriculum"] [data-ms-field="module.lesson_count"]')
      .forEach(function (el) { el.textContent = String(total); });

    var fill = queryToken(root, 'progress-fill');
    if (fill) fill.style.width = pct + '%';
  }

  function paintVideo(root, lesson) {
    var rawUrl = lesson.data && lesson.data.video_url;
    if (!rawUrl) return;

    // Keep raw field available for debugging/simple text bindings.
    fillField(root, 'lesson.video_url', rawUrl);

    // Preferred embed target: iframe/video wrapper on lesson page.
    var playerNodes = queryTokenAll(root, 'video-player');
    var embedUrl = toEmbedUrl(rawUrl);
    playerNodes.forEach(function (el) {
      if (el.tagName === 'IFRAME') {
        el.setAttribute('src', embedUrl || rawUrl);
        el.setAttribute('allowfullscreen', 'true');
      } else if (el.tagName === 'VIDEO') {
        el.setAttribute('src', rawUrl);
        el.setAttribute('controls', 'true');
      } else if (embedUrl) {
        // For Webflow embed divs, inject a real iframe so video actually plays.
        if (!el.style.minHeight) el.style.minHeight = VIDEO_PLAYER_MIN_HEIGHT;
        el.innerHTML = '<iframe src="' + embedUrl + '"'
          + ' frameborder="0"'
          + ' allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share"'
          + ' allowfullscreen'
          + ' style="width:100%;height:100%;border:0;"></iframe>';
        el.setAttribute('data-video-src', embedUrl);
      } else {
        el.setAttribute('data-video-src', rawUrl);
      }
    });

    // Optional CTA/link that should open the current lesson.
    root.querySelectorAll(tokenSelector('watch-lesson') + ',[data-ms-code="detail-link"]')
      .forEach(function (el) { setDetailLink(el, recordId(lesson)); });

    // Optional poster/thumbnail area for the player card.
    var thumbUrl = deriveVideoThumbnail(rawUrl);
    if (thumbUrl) {
      queryTokenAll(root, 'video-thumb').concat(queryTokenAll(root, 'preview-thumb')).forEach(function (el) {
        if (el.tagName === 'IMG') el.setAttribute('src', thumbUrl);
        else {
          el.style.backgroundImage = 'url("' + thumbUrl + '")';
          el.style.backgroundSize = 'cover';
          el.style.backgroundPosition = 'center';
        }
      });
    }
  }

  function paintLessonPagination(root, lesson, moduleLessons, data) {
    var i = moduleLessons.findIndex(function (l) { return recordId(l) === recordId(lesson); });
    var prev = i > 0 ? moduleLessons[i - 1] : null;
    var next = i >= 0 && i < moduleLessons.length - 1 ? moduleLessons[i + 1] : null;
    var prevLabel = '← Previous Lesson';
    var nextLabel = 'Next Lesson →';

    // Fall through to the neighbouring module when there's no prev/next in
    // the current one — so the last lesson of a module links to the first
    // lesson of the next module, and vice versa.
    if ((!prev || !next) && data && data.modules && data.lessons) {
      var courseId = idOf(lesson.data.course);
      var courseMods = data.modules
        .filter(function (m) { return idOf(m.data.course) === courseId; })
        .sort(byOrder);
      var modIdx = courseMods.findIndex(function (m) { return recordId(m) === idOf(lesson.data.module); });

      if (!prev && modIdx > 0) {
        var prevModId = recordId(courseMods[modIdx - 1]);
        var prevModLessons = data.lessons
          .filter(function (l) { return idOf(l.data.module) === prevModId; })
          .sort(byOrder);
        if (prevModLessons.length) {
          prev = prevModLessons[prevModLessons.length - 1];
          prevLabel = '← Previous Module';
        }
      }
      if (!next && modIdx !== -1 && modIdx < courseMods.length - 1) {
        var nextModId = recordId(courseMods[modIdx + 1]);
        var nextModLessons = data.lessons
          .filter(function (l) { return idOf(l.data.module) === nextModId; })
          .sort(byOrder);
        if (nextModLessons.length) {
          next = nextModLessons[0];
          nextLabel = 'Next Module →';
        }
      }
    }

    var prevCard = queryToken(root, 'prev-lesson') || queryToken(root, 'prev-module');
    var nextCard = queryToken(root, 'next-lesson') || queryToken(root, 'next-module');

    if (prevCard) {
      if (prev) {
        setDetailLink(prevCard, recordId(prev));
        setLabel(prevCard, 'prev-label', prevLabel);
        fillField(prevCard, 'lesson.title', prev.data.title);
      } else {
        prevCard.removeAttribute('href');
        setLabel(prevCard, 'prev-label', 'Current Lesson');
        fillField(prevCard, 'lesson.title', lesson.data.title);
      }
    }

    if (nextCard) {
      if (next) {
        setDetailLink(nextCard, recordId(next));
        setLabel(nextCard, 'next-label', nextLabel);
        fillField(nextCard, 'lesson.title', next.data.title);
      } else {
        nextCard.removeAttribute('href');
        setLabel(nextCard, 'next-label', 'Current Lesson');
        fillField(nextCard, 'lesson.title', lesson.data.title);
      }
    }
  }

  function paintBreakdown(root, lesson, rows) {
    var ctn = root.querySelector('[data-ms-code="lesson-breakdown"]');
    if (!ctn) return;
    var tpl = ctn.querySelector('[data-ms-code="breakdown-template"]');
    if (!tpl) return;

    clearClones(ctn);
    tpl.style.display = 'none';

    var list = (rows || [])
      .filter(function (r) { return idOf(r.data.lesson) === recordId(lesson); })
      .sort(byOrder);

    list.forEach(function (item) {
      var row = tpl.cloneNode(true);
      row.removeAttribute('data-ms-code');
      row.setAttribute('data-ms-clone', 'true');
      row.style.display = '';
      fillField(row, 'lesson_breakdown.content', item.data.content);
      tpl.parentNode.insertBefore(row, tpl);
    });
  }

  function paintResources(root, lesson, rows) {
    var ctn = root.querySelector('[data-ms-code="resources"]');
    if (!ctn) return;
    var tpl = ctn.querySelector('[data-ms-code="resource-template"]');
    if (!tpl) return;

    clearClones(ctn);
    tpl.style.display = 'none';

    var list = (rows || [])
      .filter(function (r) { return idOf(r.data.lesson) === recordId(lesson); })
      .sort(byOrder);

    setLabel(ctn, 'resources-count', String(list.length) + ' ITEMS');

    list.forEach(function (item) {
      var row = tpl.cloneNode(true);
      row.removeAttribute('data-ms-code');
      row.setAttribute('data-ms-clone', 'true');
      row.style.display = '';
      fillField(row, 'reference.title', item.data.title);
      fillField(row, 'reference.type', item.data.type);
      fillField(row, 'reference.url', item.data.url);
      if (item.data.url) row.setAttribute('href', item.data.url);
      tpl.parentNode.insertBefore(row, tpl);
    });
  }

  function wireMarkComplete(root, lesson, member, ms, progressRows, tables, enrollments) {
    var buttons = queryTokenAll(root, 'mark-complete');
    if (!buttons.length || !member || !ms) return;
    var lessonId = recordId(lesson);
    var courseId = idOf(lesson.data.course);
    var doneState = isDone(lessonId, progressRows || []);
    paintCompletionState(root, doneState);

    // Mark-complete requires an active enrolment for this course. Toggle an
    // optional `data-ms-show-if="enrolled"` variant group (`yes`/`no`) so the
    // design can show an "Enrol to track progress" CTA instead, and hide the
    // mark-complete buttons themselves when the member isn't enrolled.
    var enrolled = (enrollments || []).some(function (e) {
      if (idOf(e.data.course) !== courseId) return false;
      var s = String(e.data.status || 'active').toLowerCase();
      return s !== 'dropped';
    });
    toggleVariants(root, 'enrolled', enrolled ? 'yes' : 'no');
    if (!enrolled) {
      buttons.forEach(function (btn) { btn.style.display = 'none'; });
      return;
    }

    buttons.forEach(function (btn) {
      btn.addEventListener('click', async function (e) {
        e.preventDefault();
        var now = new Date().toISOString();
        var payloadDone = {
          owner: member.id,
          lesson: lessonId,
          course: idOf(lesson.data.course),
          completed: 1,
          completed_at: now,
          last_watched_at: now
        };
        var payloadTodo = {
          owner: member.id,
          lesson: lessonId,
          course: idOf(lesson.data.course),
          completed: 0,
          completed_at: null,
          last_watched_at: now
        };
        try {
          // Re-read fresh: a lesson-open write (or another tab) may have
          // added a row since page load. Trusting the stale boot snapshot
          // here would create a duplicate instead of updating.
          var fresh = await loadProgressFresh(ms, tables, member.id);
          var existing = fresh.find(function (p) { return idOf(p.data.lesson) === lessonId; }) || null;
          if (existing) {
            await writeWithRetry(function () {
              return ms.updateDataRecord({
                recordId: recordId(existing),
                data: doneState ? payloadTodo : payloadDone
              });
            }, 'mark-complete');
          } else {
            await writeWithRetry(function () {
              return ms.createDataRecord({ table: tables.progress, data: payloadDone });
            }, 'mark-complete');
          }
          doneState = !doneState;
          paintCompletionState(root, doneState);
          window.MSDataCache.invalidate(tables.progress);
          window.location.reload();
        } catch (err) {
          console.error(LABEL + ' mark complete failed', err);
        }
      });
    });
  }

  // Records that the member opened this lesson: creates a lesson_progress
  // row (completed: 0) the first time, or re-stamps last_watched_at on
  // later visits. Re-reads fresh data before any create so it can never
  // insert a second row for the same lesson.
  async function recordLessonOpen(lesson, member, ms, progressRows, tables) {
    if (!lesson || !member || !ms || !window.MSDataCache) return;
    var lessonId = recordId(lesson);
    if (!lessonId) return;

    try {
      var existing = (progressRows || []).find(function (p) {
        return idOf(p.data.lesson) === lessonId;
      }) || null;

      // The boot snapshot can be stale (sessionStorage cache). If it shows
      // no row, re-confirm against fresh data before creating one.
      if (!existing) {
        var fresh = await loadProgressFresh(ms, tables, member.id);
        existing = fresh.find(function (p) { return idOf(p.data.lesson) === lessonId; }) || null;
      }

      var now = new Date().toISOString();

      if (existing) {
        // Row already exists — only re-stamp last_watched_at if it's stale,
        // to avoid an API write on every page load.
        var last = existing.data && existing.data.last_watched_at;
        var recent = last && (Date.now() - new Date(last).getTime()) < LAST_WATCHED_TOUCH_MS;
        if (recent) return;
        await writeWithRetry(function () {
          return ms.updateDataRecord({ recordId: recordId(existing), data: { last_watched_at: now } });
        }, 'lesson-open');
      } else {
        await writeWithRetry(function () {
          return ms.createDataRecord({
            table: tables.progress,
            data: {
              owner: member.id,
              lesson: lessonId,
              course: idOf(lesson.data.course),
              completed: 0,
              completed_at: null,
              last_watched_at: now
            }
          });
        }, 'lesson-open');
      }
      window.MSDataCache.invalidate(tables.progress);
    } catch (err) {
      console.error(LABEL + ' record lesson open failed', err);
    }
  }

  // Fresh, owner-scoped lesson_progress read — bypasses the 30s cache so
  // create-vs-update decisions are made against authoritative data.
  function loadProgressFresh(ms, tables, memberId) {
    window.MSDataCache.invalidate(tables.progress);
    return window.MSDataCache.load(ms, tables.progress, { owner: { equals: memberId } });
  }

  // Run a single write through MSDataCache.runWrites so it inherits 429
  // backoff + retry. Falls back to a plain call if runWrites is unavailable.
  function writeWithRetry(thunk, label) {
    if (window.MSDataCache && typeof window.MSDataCache.runWrites === 'function') {
      return window.MSDataCache.runWrites([thunk], { label: label, stopOnError: true })
        .then(function (o) { return o.results[0]; });
    }
    return Promise.resolve().then(thunk);
  }

  function paintCompletionState(root, done) {
    var buttons = queryTokenAll(root, 'mark-complete');
    if (!buttons.length) return;
    buttons.forEach(function (btn) {
      var variant = String(btn.getAttribute('data-ms-show-value') || '');
      var activeState = done ? 'done' : 'todo';
      var isActiveVariant = variant === activeState || !variant;
      btn.setAttribute('aria-disabled', isActiveVariant ? 'false' : 'true');
      btn.classList.toggle('is-disabled', !isActiveVariant);
    });

    // UI copy/icons should be handled by Webflow state variants.
    toggleVariants(root, 'complete', done ? 'done' : 'todo');
  }

  function wireSaveActions(root, lesson, course, member, ms, savedLessons, tables) {
    if (!member || !ms) return;
    var lessonId = recordId(lesson);
    var courseId = course ? recordId(course) : idOf(lesson.data.course);

    var saveLessonBtns = queryTokenAll(root, 'save-lesson');

    var savedLessonRow = (savedLessons || []).find(function (r) { return idOf(r.data.lesson) === lessonId; }) || null;

    paintSaveState(root, 'lesson', !!savedLessonRow);

    saveLessonBtns.forEach(function (saveLessonBtn) {
      saveLessonBtn.addEventListener('click', async function (e) {
        e.preventDefault();
        try {
          if (savedLessonRow) {
            await writeWithRetry(function () {
              return ms.deleteDataRecord({ recordId: recordId(savedLessonRow) });
            }, 'save-lesson');
            savedLessonRow = null;
          } else {
            await writeWithRetry(function () {
              return ms.createDataRecord({
                table: tables.savedLessons,
                data: { owner: member.id, lesson: lessonId, course: courseId, saved_at: new Date().toISOString() }
              });
            }, 'save-lesson');
            var fresh = await window.MSDataCache.load(ms, tables.savedLessons, { owner: { equals: member.id } });
            savedLessonRow = fresh.find(function (r) { return idOf(r.data.lesson) === lessonId; }) || null;
          }
          window.MSDataCache.invalidate(tables.savedLessons);
          paintSaveState(root, 'lesson', !!savedLessonRow);
        } catch (err) {
          console.error(LABEL + ' toggle save lesson failed', err);
        }
      });
    });
  }

  function paintSaveState(root, kind, saved) {
    // UI copy/icons should be handled by Webflow state variants.
    toggleVariants(root, 'save-' + kind, saved ? 'saved' : 'unsaved');
  }

  function wireViewCourse(root, course) {
    if (!course) return;
    queryTokenAll(root, 'view-course').forEach(function (el) {
      setDetailLink(el, recordId(course));
    });
  }

  function paintSidebarCurriculum(root, lesson, mod, moduleLessons, moduleProgress) {
    var ctn = root.querySelector('[data-ms-code="curriculum"]');
    if (!ctn) return;
    var tpl = ctn.querySelector('[data-ms-code="lesson-template"]');
    if (!tpl) return;

    clearClones(ctn);
    tpl.style.display = 'none';

    // module title link in sidebar header
    var moduleLink = queryToken(ctn, 'module-link');
    if (moduleLink && mod) setDetailLink(moduleLink, recordId(mod));
    fillField(ctn, 'module.title', mod && mod.data.title);

    var unlockedIndex = firstIncompleteIndex(moduleLessons, moduleProgress);

    moduleLessons.forEach(function (l, idx) {
      var row = tpl.cloneNode(true);
      row.removeAttribute('data-ms-code');
      row.setAttribute('data-ms-clone', 'true');
      row.style.display = '';

      var done = isDone(recordId(l), moduleProgress);
      var current = recordId(l) === recordId(lesson);
      var locked = !done && !current && unlockedIndex !== -1 && idx > unlockedIndex;

      fillField(row, 'lesson.title', l.data.title);
      fillField(row, 'lesson.order', l.data.order);
      fillField(row, 'lesson.duration_minutes', l.data.duration_minutes || 0);

      var status = done ? 'done' : (current ? 'active' : (locked ? 'locked' : 'todo'));
      if (status === 'locked' && !row.querySelector('[data-ms-show-if="status"][data-ms-show-value="locked"]')) {
        status = 'todo';
      }
      // Expose the row's status as a data attribute so the whole row can be
      // styled in Webflow with a selector like `.lesson_item[data-status="active"]`.
      row.setAttribute('data-status', status);
      toggleVariants(row, 'status', status);

      if (locked) {
        row.removeAttribute('href');
        row.setAttribute('aria-disabled', 'true');
      } else {
        row.removeAttribute('aria-disabled');
        setDetailLink(row, recordId(l));
      }

      tpl.parentNode.insertBefore(row, tpl);
    });
  }

  function findLesson(lessons, id, slug) {
    if (id) {
      var hit = lessons.find(function (l) { return recordId(l) === id; });
      if (hit) return hit;
    }
    if (slug) {
      var bySlug = lessons.find(function (l) { return l.data && l.data.slug === slug; });
      if (bySlug) return bySlug;
    }
    return null;
  }

  function toEmbedUrl(url) {
    if (!url || typeof url !== 'string') return null;
    var u;
    try { u = new URL(url); } catch (e) { return null; }
    var host = (u.hostname || '').toLowerCase();

    if (host.indexOf('youtube.com') !== -1 || host.indexOf('youtu.be') !== -1) {
      var yt = youtubeId(u);
      return yt ? 'https://www.youtube.com/embed/' + yt : null;
    }
    if (host.indexOf('vimeo.com') !== -1) {
      var vm = vimeoId(u);
      return vm ? 'https://player.vimeo.com/video/' + vm : null;
    }
    return null;
  }

  function deriveVideoThumbnail(url) {
    if (!url || typeof url !== 'string') return null;
    var u;
    try { u = new URL(url); } catch (e) { return null; }
    var host = (u.hostname || '').toLowerCase();
    if (host.indexOf('youtube.com') !== -1 || host.indexOf('youtu.be') !== -1) {
      var yt = youtubeId(u);
      return yt ? 'https://i.ytimg.com/vi/' + yt + '/hqdefault.jpg' : null;
    }
    if (host.indexOf('vimeo.com') !== -1) {
      var vm = vimeoId(u);
      return vm ? 'https://vumbnail.com/' + vm + '.jpg' : null;
    }
    return null;
  }

  function youtubeId(u) {
    if (!u) return null;
    var host = (u.hostname || '').toLowerCase();
    if (host.indexOf('youtu.be') !== -1) {
      var shortId = (u.pathname || '').replace(/^\/+/, '').split('/')[0];
      return shortId || null;
    }
    var q = u.searchParams.get('v');
    if (q) return q;
    var parts = (u.pathname || '').split('/').filter(Boolean);
    var e = parts.indexOf('embed');
    if (e !== -1 && parts[e + 1]) return parts[e + 1];
    return null;
  }

  function vimeoId(u) {
    if (!u) return null;
    var parts = (u.pathname || '').split('/').filter(Boolean);
    for (var i = parts.length - 1; i >= 0; i--) {
      if (/^\d+$/.test(parts[i])) return parts[i];
    }
    return null;
  }

  function firstIncompleteIndex(lessons, progress) {
    for (var i = 0; i < lessons.length; i++) {
      if (!isDone(recordId(lessons[i]), progress)) return i;
    }
    return -1;
  }

  function isDone(lessonId, progress) {
    var rec = progress.find(function (p) { return idOf(p.data.lesson) === lessonId; });
    return !!(rec && (rec.data.completed | 0) === 1);
  }

  function fillField(scope, key, value) {
    if (value == null || value === '') return;
    scope.querySelectorAll('[data-ms-field="' + key + '"]').forEach(function (el) { el.textContent = value; });
  }

  function setLabel(scope, key, value) {
    if (value == null) return;
    queryTokenAll(scope, key).forEach(function (el) { el.textContent = value; });
  }

  function toggleVariants(scope, attr, value) {
    scope.querySelectorAll('[data-ms-show-if="' + attr + '"]').forEach(function (el) {
      el.style.display = el.getAttribute('data-ms-show-value') === String(value) ? '' : 'none';
    });
  }

  function setDetailLink(el, recId) {
    if (!el || !recId) return;
    var page = el.getAttribute('ms-code-detail-page');
    if (!page) return;
    var param = el.getAttribute('ms-code-id-param') || 'id';
    el.setAttribute('href', page + '?' + param + '=' + recId);
  }

  function clearClones(scope) {
    scope.querySelectorAll('[data-ms-clone="true"]').forEach(function (n) { n.parentNode.removeChild(n); });
  }


  function tableConfig(root) {
    return {
      course: root.getAttribute('ms-code-table-course') || 'courses',
      module: root.getAttribute('ms-code-table-module') || 'modules',
      lesson: root.getAttribute('ms-code-table-lesson') || 'lessons',
      progress: root.getAttribute('ms-code-table-progress') || 'lesson_progress',
      savedLessons: root.getAttribute('ms-code-table-saved-lessons') || 'saved_lessons',
      breakdown: root.getAttribute('ms-code-table-breakdown') || 'lesson_breakdown',
      reference: root.getAttribute('ms-code-table-reference') || 'reference',
      enrollment: root.getAttribute('ms-code-table-enrollment') || 'enrollments'
    };
  }

  function tokenSelector(token) {
    return '[data-ms-code="' + token + '"]';
  }

  function queryToken(scope, token) {
    return scope ? scope.querySelector(tokenSelector(token)) : null;
  }

  function queryTokenAll(scope, token) {
    return scope ? Array.prototype.slice.call(scope.querySelectorAll(tokenSelector(token))) : [];
  }

  function idOf(ref) {
    if (!ref) return null;
    if (typeof ref === 'string') return ref;
    if (Array.isArray(ref)) return idOf(ref[0]);
    if (typeof ref === 'object') return ref.id || ref._id || null;
    return null;
  }

  function recordId(rec) {
    if (!rec) return null;
    return rec.id || rec._id || rec.recordId || null;
  }

  function byOrder(a, b) { return (a.data.order || 0) - (b.data.order || 0); }
  function pad2(n) { var x = parseInt(n, 10); return isNaN(x) ? String(n || '') : (x < 10 ? '0' + x : String(x)); }
  function getUrlParam(name) { try { return new URL(window.location.href).searchParams.get(name); } catch (e) { return null; } }
})();

/* ===================== module-detail.js ===================== */
(function () {
  'use strict';

  var LABEL = '[module-detail]';

  document.addEventListener('DOMContentLoaded', function () { boot(); });

  async function boot() {
    var root = document.querySelector('[data-ms-code="module-page"]');
    if (!root) return;

    if (!window.$memberstackDom || !window.MSDataCache) {
      console.warn(LABEL + ' missing $memberstackDom or MSDataCache');
      return;
    }

    var ms = window.$memberstackDom;
    var TABLES = tableConfig(root);
    var idParam = root.getAttribute('ms-code-id-param') || 'id';
    var slugParam = root.getAttribute('ms-code-slug-param') || 'slug';
    var moduleId = getUrlParam(idParam);
    var moduleSlug = getUrlParam(slugParam);

    if (!moduleId && !moduleSlug) {
      console.warn(LABEL + ' no ?' + idParam + ' or ?' + slugParam + ' in URL');
      return;
    }

    try {
      var member = await window.MSDataCache.getMember(ms);
      var memberId = member ? member.id : null;
      var ownerWhere = memberId ? { owner: { equals: memberId } } : null;

      var loaded = await Promise.all([
        window.MSDataCache.load(ms, TABLES.course, null),
        window.MSDataCache.load(ms, TABLES.module, null),
        window.MSDataCache.load(ms, TABLES.lesson, null),
        ownerWhere ? window.MSDataCache.load(ms, TABLES.progress, ownerWhere) : Promise.resolve([])
      ]);

      var data = {
        courses: loaded[0],
        modules: loaded[1],
        lessons: loaded[2],
        progress: loaded[3]
      };

      var mod = findModule(data.modules, moduleId, moduleSlug);
      if (!mod) {
        console.warn(LABEL + ' module not found for id="' + moduleId + '" slug="' + moduleSlug + '"');
        return;
      }

      render(root, mod, data);
    } catch (err) {
      console.error(LABEL + ' boot failed', err);
    }
  }

  function render(root, mod, data) {
    var moduleId = moduleRecordId(mod);
    var courseId = idOf(mod.data.course);
    var course = data.courses.find(function (c) { return c.id === courseId; }) || null;

    var courseModules = data.modules
      .filter(function (m) { return idOf(m.data.course) === courseId; })
      .sort(byOrder);
    var moduleIndex = courseModules.findIndex(function (m) { return moduleRecordId(m) === moduleId; });

    var lessons = data.lessons
      .filter(function (l) { return idOf(l.data.module) === moduleId; })
      .sort(byOrder);
    var progress = data.progress.filter(function (p) { return idOf(p.data.course) === courseId; });

    paintHeader(root, mod, course, courseModules, moduleIndex, lessons, progress);
    paintBreadcrumbs(root, course, mod);
    paintLessonList(root, lessons, progress);
    paintPagination(root, courseModules, moduleIndex);
  }

  function paintHeader(root, mod, course, courseModules, moduleIndex, lessons, progress) {
    var completed = lessons.filter(function (l) { return isLessonDone(l.id, progress); }).length;
    var total = lessons.length || (mod.data.lesson_count || 0);
    var hours = estimateHours(lessons);
    var pct = total > 0 ? Math.round((completed / total) * 100) : 0;

    fillField(root, 'module.title', mod.data.title);
    fillField(root, 'module.description', mod.data.description || '');
    fillField(root, 'module.order', mod.data.order);
    fillField(root, 'module.lesson_count', total);

    setLabel(root, 'module-meta',
      'Module ' + pad2(moduleIndex + 1) + ' of ' + pad2(courseModules.length)
      + ' · ' + total + ' Lessons · ' + hours);
    setLabel(root, 'progress-label', completed + ' / ' + total + ' Lessons');

    var fill = queryToken(root, 'progress-fill');
    if (fill) fill.style.width = pct + '%';

    if (course) {
      fillField(root, 'course.title', course.data.title);
    }
  }

  function paintBreadcrumbs(root, course, mod) {
    var learnLink = queryToken(root, 'crumb-learn');
    var courseLink = queryToken(root, 'crumb-course');
    var moduleLink = queryToken(root, 'crumb-module');

    if (learnLink && !learnLink.getAttribute('href')) {
      console.warn(LABEL + ' crumb-learn has no href; set it in markup');
    }
    if (courseLink && course) setDetailLink(courseLink, course.id);
    if (moduleLink) setDetailLink(moduleLink, mod.id);
  }

  function paintLessonList(root, lessons, progress) {
    var list = root.querySelector('[data-ms-code="lesson-list"]');
    var tpl = list ? list.querySelector('[data-ms-code="lesson-template"]') : null;
    if (!tpl) return;

    clearClones(list);
    tpl.style.display = 'none';

    // Strict drip: the first incomplete lesson is the only unlocked
    // incomplete lesson ("active"). Any incomplete lesson after that is locked.
    var unlockedIndex = firstIncompleteIndex(lessons, progress);

    lessons.forEach(function (lesson, idx) {
      var row = tpl.cloneNode(true);
      row.removeAttribute('data-ms-code');
      row.setAttribute('data-ms-clone', 'true');
      row.style.display = '';

      var done = isLessonDone(lesson.id, progress);
      var current = !done && idx === unlockedIndex;
      var locked = !done && unlockedIndex !== -1 && idx > unlockedIndex;

      fillField(row, 'lesson.title', lesson.data.title);
      fillField(row, 'lesson.order', lesson.data.order);
      fillField(row, 'lesson.duration_minutes', lesson.data.duration_minutes || 0);

      setLabel(row, 'lesson-order-label', 'Lesson ' + pad2(lesson.data.order || (idx + 1)));
      setLabel(row, 'lesson-duration-label', String(lesson.data.duration_minutes || 0) + ' min');

      var status = done ? 'done' : (current ? 'active' : (locked ? 'locked' : 'todo'));
      // Expose status as a data attribute so the whole row can be styled in
      // Webflow with `.lesson_item[data-status="active"]`.
      row.setAttribute('data-status', status);
      toggleVariants(row, 'status', status);
      toggleVariants(row, 'action', done ? 'replay' : (current ? 'continue' : (locked ? 'locked' : 'start')));

      if (locked) {
        row.removeAttribute('href');
        row.setAttribute('aria-disabled', 'true');
      } else {
        setDetailLink(row, lesson.id);
      }

      tpl.parentNode.insertBefore(row, tpl);
    });
  }

  function paintPagination(root, courseModules, moduleIndex) {
    // Guard against unexpected index misses (e.g. mixed id shapes).
    // If this happens, we keep pagination in empty state rather than
    // linking to an incorrect module.
    if (moduleIndex < 0 || moduleIndex >= courseModules.length) {
      console.warn(LABEL + ' pagination: moduleIndex out of range', {
        moduleIndex: moduleIndex, total: courseModules.length
      });
      moduleIndex = -1;
    }

    var current = moduleIndex >= 0 ? courseModules[moduleIndex] : null;
    var prev = moduleIndex > 0 ? courseModules[moduleIndex - 1] : null;
    var next = moduleIndex >= 0 && moduleIndex < courseModules.length - 1 ? courseModules[moduleIndex + 1] : null;

    var prevCard = queryToken(root, 'prev-module');
    var nextCard = queryToken(root, 'next-module');

    if (prevCard) {
      if (!prev) {
        toggleVariants(prevCard, 'state', 'empty');
        prevCard.removeAttribute('href');
        // Optional fallback copy for first module pages.
        if (current) {
          fillField(prevCard, 'module.title', current.data.title);
          fillField(prevCard, 'module.lesson_count', current.data.lesson_count || 0);
          setLabel(prevCard, 'prev-label', 'Current Module');
        }
      } else {
        toggleVariants(prevCard, 'state', 'ready');
        fillField(prevCard, 'module.title', prev.data.title);
        fillField(prevCard, 'module.lesson_count', prev.data.lesson_count || 0);
        setLabel(prevCard, 'prev-label', '← Previous Module');
        setDetailLink(prevCard, moduleRecordId(prev));
      }
    }

    if (nextCard) {
      if (!next) {
        toggleVariants(nextCard, 'state', 'empty');
        nextCard.removeAttribute('href');
        // Optional fallback copy for last module pages.
        if (current) {
          fillField(nextCard, 'module.title', current.data.title);
          fillField(nextCard, 'module.lesson_count', current.data.lesson_count || 0);
          setLabel(nextCard, 'next-label', 'Current Module');
        }
      } else {
        toggleVariants(nextCard, 'state', 'ready');
        fillField(nextCard, 'module.title', next.data.title);
        fillField(nextCard, 'module.lesson_count', next.data.lesson_count || 0);
        setLabel(nextCard, 'next-label', 'Next Module →');
        setDetailLink(nextCard, moduleRecordId(next));
      }
    }
  }

  function findModule(modules, id, slug) {
    if (id) {
      var byId = modules.find(function (m) { return moduleRecordId(m) === id; });
      if (byId) return byId;
    }
    if (slug) {
      var bySlug = modules.find(function (m) { return (m.data && m.data.slug) === slug; });
      if (bySlug) return bySlug;
    }
    return null;
  }

  function isLessonDone(lessonId, progress) {
    var rec = progress.find(function (p) { return idOf(p.data.lesson) === lessonId; });
    return !!(rec && (rec.data.completed | 0) === 1);
  }

  function firstIncompleteIndex(lessons, progress) {
    for (var i = 0; i < lessons.length; i++) {
      if (!isLessonDone(lessons[i].id, progress)) return i;
    }
    return -1;
  }

  function estimateHours(lessons) {
    var mins = lessons.reduce(function (sum, l) { return sum + (parseInt(l.data.duration_minutes || 0, 10) || 0); }, 0);
    if (!mins) return '~0 hrs';
    var hrs = mins / 60;
    var rounded = Math.round(hrs * 10) / 10;
    return '~' + rounded + ' hrs';
  }

  function fillField(scope, key, value) {
    if (value == null || value === '') return;
    scope.querySelectorAll('[data-ms-field="' + key + '"]').forEach(function (el) {
      var flag = el.getAttribute('data-ms-code');
      if (flag === 'pad') el.textContent = pad2(value);
      else el.textContent = value;
    });
  }

  function setLabel(scope, key, value) {
    if (value == null) return;
    queryTokenAll(scope, key).forEach(function (el) { el.textContent = value; });
  }

  function toggleVariants(scope, attr, activeValue) {
    scope.querySelectorAll('[data-ms-show-if="' + attr + '"]').forEach(function (n) {
      n.style.display = (n.getAttribute('data-ms-show-value') === String(activeValue)) ? '' : 'none';
    });
  }

  function setDetailLink(el, recordId) {
    if (!el || !recordId) return;
    var page = el.getAttribute('ms-code-detail-page');
    if (!page) return;
    var param = el.getAttribute('ms-code-id-param') || 'id';
    el.setAttribute('href', page + '?' + param + '=' + recordId);
  }

  function clearClones(scope) {
    scope.querySelectorAll('[data-ms-clone="true"]').forEach(function (n) { n.parentNode.removeChild(n); });
  }


  // Table config must be attribute-driven on the page wrapper.
  // Defaults keep backward compatibility.
  function tableConfig(root) {
    return {
      course: root.getAttribute('ms-code-table-course') || 'courses',
      module: root.getAttribute('ms-code-table-module') || 'modules',
      lesson: root.getAttribute('ms-code-table-lesson') || 'lessons',
      progress: root.getAttribute('ms-code-table-progress') || 'lesson_progress'
    };
  }

  // Token selectors (MS-only).
  function tokenSelector(token) {
    return '[data-ms-code="' + token + '"]';
  }

  function queryToken(scope, token) {
    return scope ? scope.querySelector(tokenSelector(token)) : null;
  }

  function queryTokenAll(scope, token) {
    return scope ? Array.prototype.slice.call(scope.querySelectorAll(tokenSelector(token))) : [];
  }

  function getUrlParam(name) {
    try { return new URL(window.location.href).searchParams.get(name); } catch (e) { return null; }
  }

  function idOf(ref) {
    if (!ref) return null;
    if (typeof ref === 'string') return ref;
    if (Array.isArray(ref)) return idOf(ref[0]);
    if (typeof ref === 'object') return ref.id || ref._id || null;
    return null;
  }

  function moduleRecordId(mod) {
    if (!mod) return null;
    return mod.id || mod._id || mod.recordId || null;
  }

  function byOrder(a, b) { return (a.data.order || 0) - (b.data.order || 0); }

  function pad2(n) {
    var x = parseInt(n, 10);
    if (isNaN(x)) return String(n == null ? '' : n);
    return x < 10 ? '0' + x : String(x);
  }
})();

