(function () {
  'use strict';

  var ROOT_SELECTOR = '[data-ms-code="all-courses-page"]';
  var STACK_SELECTOR = '[data-ms-code="course-stack"]';
  var COURSE_TEMPLATE_SELECTOR = '[data-ms-code="course-template"]';
  var MODULE_TEMPLATE_SELECTOR = '[data-ms-code="module-template"]';
  var MODULE_PREVIEW_LIMIT = 2;

  document.addEventListener('DOMContentLoaded', function () { boot(); });

  async function boot() {
    if (!window.$memberstackDom) return;

    var root = document.querySelector(ROOT_SELECTOR);
    if (!root) return;
    showListState(root, 'list-loading');

    var tableCourse = tableAttr(root, 'ms-code-table-course', 'courses');
    var tableModule = tableAttr(root, 'ms-code-table-module', 'modules');
    var tableLesson = tableAttr(root, 'ms-code-table-lesson', 'lessons');

    try {
      var ms = window.$memberstackDom;
      var loaded = await Promise.all([
        loadAll(ms, tableCourse, null),
        loadAll(ms, tableModule, null),
        loadAll(ms, tableLesson, null)
      ]);

      var courses = (loaded[0] || []).slice().sort(byOrderAsc);
      var modules = loaded[1] || [];
      var lessons = loaded[2] || [];

      paintGlobalStats(root, courses, modules, lessons);
      paintCourseStack(root, courses, modules, lessons);
    } catch (err) {
      console.error('[all-courses] boot failed', err);
      showListState(root, 'list-error');
    }
  }

  async function loadAll(ms, table, where) {
    if (window.MSDataCache && typeof window.MSDataCache.load === 'function') {
      return window.MSDataCache.load(ms, table, where || null);
    }
    return loadAllRaw(ms, table, where);
  }

  async function loadAllRaw(ms, table, where) {
    var all = [];
    var offset = 0;
    var limit = 100;
    var pageCount = 0;
    while (pageCount < 50) {
      var response = await ms.getData({
        dataTableId: table,
        where: where || undefined,
        limit: limit,
        offset: offset
      });
      var rows = response && response.data ? response.data : [];
      all = all.concat(rows);
      if (rows.length < limit) break;
      offset += limit;
      pageCount++;
    }
    return all;
  }

  function paintGlobalStats(root, courses, modules, lessons) {
    setText(root, '[data-ms-code="courses-count"]', String(courses.length));
    setText(root, '[data-ms-code="modules-count"]', String(modules.length));
    setText(root, '[data-ms-code="lessons-count"]', String(lessons.length));
  }

  function paintCourseStack(root, courses, modules, lessons) {
    var stack = root.querySelector(STACK_SELECTOR);
    if (!stack) return;

    var tpl = stack.querySelector(COURSE_TEMPLATE_SELECTOR);
    if (!tpl) return;

    clearClones(stack);
    tpl.style.display = 'none';

    if (!courses.length) {
      showListState(root, 'list-empty');
      return;
    }

    courses.forEach(function (course) {
      var card = tpl.cloneNode(true);
      card.removeAttribute('data-ms-code');
      card.setAttribute('data-ms-clone', 'true');
      card.style.display = '';

      paintCourseCard(card, course, modules, lessons);
      tpl.parentNode.insertBefore(card, tpl);
    });

    showListState(root, 'ready');
  }

  function paintCourseCard(card, course, modules, lessons) {
    var courseId = course && course.id;
    var courseData = (course && course.data) || {};

    var modulesInCourse = modules
      .filter(function (m) { return idOf(m.data && m.data.course) === courseId; })
      .sort(byOrderAsc);

    var lessonsInCourse = lessons.filter(function (l) {
      return idOf(l.data && l.data.course) === courseId;
    });

    setText(card, '[data-ms-field="course.title"]', courseData.title);
    setText(card, '[data-ms-field="course.description"]', courseData.description);
    setText(card, '[data-ms-field="course.category"]', courseData.category);
    setText(card, '[data-ms-code="course-order"]', 'COURSE ' + pad2(courseData.order));
    setText(card, '[data-ms-code="course-stats"]', modulesInCourse.length + ' MODULES · ' + lessonsInCourse.length + ' LESSONS');

    paintCourseCover(card, courseData.cover_image);
    paintCourseLinks(card, courseId);
    paintModulePreview(card, modulesInCourse, lessons);
  }

  function paintCourseCover(card, imageUrl) {
    if (!imageUrl) return;
    var bg = card.querySelector('[data-ms-code="course-cover-bg"]');
    if (bg) bg.style.backgroundImage = 'url("' + imageUrl + '")';
    var img = card.querySelector('[data-ms-code="course-cover-img"]');
    if (img && img.tagName === 'IMG') img.setAttribute('src', imageUrl);
  }

  function paintCourseLinks(card, courseId) {
    if (!courseId) return;
    card.querySelectorAll('[data-ms-code="detail-link"]').forEach(function (a) {
      var page = a.getAttribute('ms-code-detail-page') || '';
      var param = a.getAttribute('ms-code-id-param') || 'id';
      if (!page) return;
      a.setAttribute('href', page + '?' + param + '=' + courseId);
    });
  }

  function paintModulePreview(card, modulesInCourse, allLessons) {
    var list = card.querySelector('[data-ms-code="module-list"]');
    if (!list) return;

    var tpl = list.querySelector(MODULE_TEMPLATE_SELECTOR);
    if (!tpl) return;

    clearClones(list);
    tpl.style.display = 'none';

    modulesInCourse.slice(0, MODULE_PREVIEW_LIMIT).forEach(function (mod) {
      var row = tpl.cloneNode(true);
      row.removeAttribute('data-ms-code');
      row.setAttribute('data-ms-clone', 'true');
      row.style.display = '';

      var modData = mod.data || {};
      var modLessons = allLessons.filter(function (l) {
        return idOf(l.data && l.data.module) === mod.id;
      });

      setText(row, '[data-ms-field="module.title"]', modData.title);
      setText(row, '[data-ms-field="module.description"]', modData.description);
      setText(row, '[data-ms-code="module-stats"]', 'MODULE ' + pad2(modData.order) + ' · ' + modLessons.length + ' LESSONS');

      list.insertBefore(row, tpl);
    });
  }

  function showListState(root, stateKey) {
    var loading = root.querySelector('[data-ms-code="list-loading"]');
    var empty = root.querySelector('[data-ms-code="list-empty"]');
    var error = root.querySelector('[data-ms-code="list-error"]');
    var showLoading = stateKey === 'list-loading';
    var showEmpty = stateKey === 'list-empty';
    var showError = stateKey === 'list-error';
    if (loading) loading.style.display = showLoading ? '' : 'none';
    if (empty) empty.style.display = showEmpty ? '' : 'none';
    if (error) error.style.display = showError ? '' : 'none';
  }

  function clearClones(root) {
    root.querySelectorAll('[data-ms-clone="true"]').forEach(function (n) {
      n.parentNode.removeChild(n);
    });
  }


  function tableAttr(root, name, fallback) {
    return root.getAttribute(name) || fallback;
  }

  function setText(root, selector, value) {
    if (value == null || value === '') return;
    var el = root.querySelector(selector);
    if (el) el.textContent = String(value);
  }

  function idOf(ref) { return ref && (ref.id || ref) || null; }

  function byOrderAsc(a, b) {
    var ao = Number(a && a.data && a.data.order || 0);
    var bo = Number(b && b.data && b.data.order || 0);
    return ao - bo;
  }

  function pad2(n) {
    if (n == null || n === '') return '--';
    return ('0' + n).slice(-2);
  }
})();

/* ===================== member-all-courses.js ===================== */
(function () {
  'use strict';

  var ROOT_SELECTOR = '[data-ms-code="member-all-courses-page"]';
  var GRID_SELECTOR = '[data-ms-code="course-grid"]';
  var COURSE_TEMPLATE_SELECTOR = '[data-ms-code="course-template"]';
  var FILTER_BAR_SELECTOR = '[data-ms-code="filter-tabs"]';
  var FILTER_TEMPLATE_SELECTOR = '[data-ms-code="filter-tab-template"]';

  document.addEventListener('DOMContentLoaded', function () { boot(); });

  async function boot() {
    if (!window.$memberstackDom) return;
    var root = document.querySelector(ROOT_SELECTOR);
    if (!root) return;
    showListState(root, 'list-loading');

    var tableCourse = tableAttr(root, 'ms-code-table-course', 'courses');
    var tableModule = tableAttr(root, 'ms-code-table-module', 'modules');
    var tableLesson = tableAttr(root, 'ms-code-table-lesson', 'lessons');
    var tableProgress = tableAttr(root, 'ms-code-table-progress', 'lesson_progress');

    try {
      var ms = window.$memberstackDom;
      var member = await getMember(ms);
      var loaded = await Promise.all([
        loadAll(ms, tableCourse, null),
        loadAll(ms, tableModule, null),
        loadAll(ms, tableLesson, null),
        member && member.id ? loadAll(ms, tableProgress, { owner: { equals: member.id } }) : Promise.resolve([])
      ]);

      var courses = (loaded[0] || []).slice().sort(byOrderAsc);
      var modules = loaded[1] || [];
      var lessons = loaded[2] || [];
      var progress = loaded[3] || [];

      paintStats(root, courses, modules, lessons);
      bindFilters(root, courses, modules, lessons, progress);
      paintCourses(root, courses, modules, lessons, progress);
      showListState(root, courses.length ? 'ready' : 'list-empty');
    } catch (err) {
      console.error('[member-all-courses] boot failed', err);
      showListState(root, 'list-error');
    }
  }

  async function loadAll(ms, table, where) {
    if (window.MSDataCache && typeof window.MSDataCache.load === 'function') {
      return window.MSDataCache.load(ms, table, where || null);
    }
    return loadAllRaw(ms, table, where);
  }

  async function loadAllRaw(ms, table, where) {
    var all = [];
    var offset = 0;
    var limit = 100;
    var pageCount = 0;
    while (pageCount < 50) {
      var response = await ms.getData({
        dataTableId: table,
        where: where || undefined,
        limit: limit,
        offset: offset
      });
      var rows = response && response.data ? response.data : [];
      all = all.concat(rows);
      if (rows.length < limit) break;
      offset += limit;
      pageCount++;
    }
    return all;
  }

  function paintStats(root, courses, modules, lessons) {
    setText(root, '[data-ms-code="courses-count"]', courses.length);
    setText(root, '[data-ms-code="modules-count"]', modules.length);
    setText(root, '[data-ms-code="lessons-count"]', lessons.length);
  }

  function bindFilters(root, courses, modules, lessons, progress) {
    var bar = root.querySelector(FILTER_BAR_SELECTOR);
    if (!bar) return;
    var template = bar.querySelector(FILTER_TEMPLATE_SELECTOR);
    if (!template) return;

    clearClones(bar);
    template.style.display = 'none';

    var groups = buildCategoryGroups(courses);
    groups.forEach(function (g, index) {
      var tab = template.cloneNode(true);
      tab.removeAttribute('data-ms-code');
      tab.setAttribute('data-ms-clone', 'true');
      tab.style.display = '';
      tab.setAttribute('data-filter', g.key);
      tab.setAttribute('data-filter-active', index === 0 ? 'true' : 'false');

      setText(tab, '[data-ms-code="filter-label"]', g.label);
      setText(tab, '[data-ms-code="filter-count"]', g.count);

      tab.addEventListener('click', function () {
        bar.querySelectorAll('[data-filter-active]').forEach(function (el) {
          el.setAttribute('data-filter-active', el === tab ? 'true' : 'false');
        });
        var rows = g.key === 'all'
          ? courses
          : courses.filter(function (c) {
              return normalize(c.data && c.data.category) === g.key;
            });
        paintCourses(root, rows, modules, lessons, progress);
      });

      template.parentNode.insertBefore(tab, template);
    });
  }

  function buildCategoryGroups(courses) {
    var byKey = Object.create(null);
    courses.forEach(function (c) {
      var category = String((c.data && c.data.category) || 'Uncategorized').trim();
      var key = normalize(category);
      if (!byKey[key]) byKey[key] = { key: key, label: category, count: 0 };
      byKey[key].count += 1;
    });

    var groups = [{ key: 'all', label: 'All', count: courses.length }];
    Object.keys(byKey).sort().forEach(function (k) { groups.push(byKey[k]); });
    return groups;
  }

  function paintCourses(root, courses, modules, lessons, progress) {
    var grid = root.querySelector(GRID_SELECTOR);
    if (!grid) return;
    var template = grid.querySelector(COURSE_TEMPLATE_SELECTOR);
    if (!template) return;

    clearClones(grid);
    template.style.display = 'none';

    courses.forEach(function (course) {
      var card = template.cloneNode(true);
      card.removeAttribute('data-ms-code');
      card.setAttribute('data-ms-clone', 'true');
      card.style.display = '';
      paintCourseCard(card, course, modules, lessons, progress);
      template.parentNode.insertBefore(card, template);
    });
  }

  function paintCourseCard(card, course, modules, lessons, progress) {
    var c = course.data || {};
    var courseId = course.id;
    var modulesInCourse = modules.filter(function (m) { return idOf(m.data && m.data.course) === courseId; });
    var lessonsInCourse = lessons.filter(function (l) { return idOf(l.data && l.data.course) === courseId; });
    var progressInCourse = (progress || []).filter(function (p) { return idOf(p.data && p.data.course) === courseId; });

    setText(card, '[data-ms-field="course.title"]', c.title);
    setText(card, '[data-ms-field="course.description"]', c.description);
    setText(card, '[data-ms-field="course.category"]', c.category);
    setText(card, '[data-ms-code="course-stats"]', lessonsInCourse.length + ' LESSONS · ' + (c.hours_estimate || '~4 HOURS'));
    setText(card, '[data-ms-code="course-modules-lessons"]', modulesInCourse.length + ' MODULES · ' + lessonsInCourse.length + ' LESSONS');

    var order = c.order == null ? '--' : ('0' + c.order).slice(-2);
    setText(card, '[data-ms-code="course-order"]', 'COURSE ' + order);
    var status = resolveCardStatus(c, lessonsInCourse.length, progressInCourse);
    toggleVariants(card, 'status', status);
    setActiveStatusLabel(card, status);

    var bg = card.querySelector('[data-ms-code="course-cover-bg"]');
    if (bg && c.cover_image) bg.style.backgroundImage = 'url("' + c.cover_image + '")';
    var img = card.querySelector('[data-ms-code="course-cover-img"]');
    if (img && img.tagName === 'IMG' && c.cover_image) img.setAttribute('src', c.cover_image);

    card.querySelectorAll('[data-ms-code="detail-link"]').forEach(function (a) {
      var page = a.getAttribute('ms-code-detail-page') || '';
      var param = a.getAttribute('ms-code-id-param') || 'id';
      if (page && courseId) a.setAttribute('href', page + '?' + param + '=' + courseId);
    });
  }

  function resolveCardStatus(courseData, lessonsTotal, progressRows) {
    if (progressRows && progressRows.length) {
      var completed = progressRows.filter(function (p) {
        return Number(p.data && p.data.completed || 0) === 1;
      }).length;
      if (lessonsTotal > 0 && completed >= lessonsTotal) return 'complete';
      // Any progress row for this course (opened or completed) counts as started.
      return 'in_progress';
    }

    var raw = normalize(courseData && (
      courseData.status ||
      courseData.course_status ||
      courseData.progress_status ||
      courseData.enrollment_status ||
      courseData.state
    ));

    var rawKey = raw.replace(/[\s-]+/g, '_');
    if (rawKey === 'complete' || rawKey === 'completed' || rawKey === 'done' || rawKey === 'finished') return 'complete';
    if (rawKey === 'in_progress' || rawKey === 'active' || rawKey === 'started') return 'in_progress';
    if (rawKey === 'not_started' || rawKey === 'new' || rawKey === 'todo') return 'not_started';

    var percent = numberFrom(courseData && (
      courseData.progress_percent ||
      courseData.completion_percent ||
      courseData.percent_complete
    ));
    if (percent >= 100) return 'complete';
    if (percent > 0) return 'in_progress';

    var completedLessons = numberFrom(courseData && (
      courseData.completed_lessons ||
      courseData.lessons_completed
    ));
    if (lessonsTotal > 0 && completedLessons >= lessonsTotal) return 'complete';
    if (completedLessons > 0) return 'in_progress';

    return 'not_started';
  }

  function toggleVariants(root, attr, activeValue) {
    root.querySelectorAll('[data-ms-show-if="' + attr + '"]').forEach(function (el) {
      var v = normalize(el.getAttribute('data-ms-show-value')).replace(/[\s-]+/g, '_');
      el.style.display = (v === activeValue) ? '' : 'none';
    });
  }

  function setActiveStatusLabel(card, status) {
    var active = card.querySelector('[data-ms-show-if="status"][data-ms-show-value="' + status + '"]');
    if (!active) return;
    setText(active, '[data-ms-code="status-label"]', statusLabel(status));
  }

  function tableAttr(root, name, fallback) {
    return root.getAttribute(name) || fallback;
  }

  async function getMember(ms) {
    if (window.MSDataCache && typeof window.MSDataCache.getMember === 'function') {
      return window.MSDataCache.getMember(ms);
    }
    var res = await ms.getCurrentMember();
    return res && res.data ? res.data : null;
  }

  function setText(root, sel, text) {
    if (text == null || text === '') return;
    var el = root.querySelector(sel);
    if (el) el.textContent = String(text);
  }

  function showListState(root, stateKey) {
    var loading = root.querySelector('[data-ms-code="list-loading"]');
    var empty = root.querySelector('[data-ms-code="list-empty"]');
    var error = root.querySelector('[data-ms-code="list-error"]');
    var showLoading = stateKey === 'list-loading';
    var showEmpty = stateKey === 'list-empty';
    var showError = stateKey === 'list-error';
    if (loading) loading.style.display = showLoading ? '' : 'none';
    if (empty) empty.style.display = showEmpty ? '' : 'none';
    if (error) error.style.display = showError ? '' : 'none';
  }

  function clearClones(root) {
    root.querySelectorAll('[data-ms-clone="true"]').forEach(function (n) {
      n.parentNode.removeChild(n);
    });
  }


  function normalize(s) { return String(s || '').trim().toLowerCase(); }
  function statusLabel(status) {
    if (status === 'complete') return 'Completed';
    if (status === 'in_progress') return 'In progress';
    return 'Not started';
  }
  function numberFrom(v) {
    if (v == null || v === '') return 0;
    var n = Number(v);
    return isNaN(n) ? 0 : n;
  }
  function idOf(ref) { return ref && (ref.id || ref) || null; }
  function byOrderAsc(a, b) {
    return Number(a && a.data && a.data.order || 0) - Number(b && b.data && b.data.order || 0);
  }
})();

/* ===================== enrolled-courses.js ===================== */
(function () {
  'use strict';

  var ROOT_SELECTOR = '[data-ms-code="enrolled-courses-page"]';
  var GRID_SELECTOR = '[data-ms-code="course-grid"]';
  var COURSE_TEMPLATE_SELECTOR = '[data-ms-code="course-template"]';
  var FILTER_BAR_SELECTOR = '[data-ms-code="filter-tabs"]';
  var FILTER_TEMPLATE_SELECTOR = '[data-ms-code="filter-tab-template"]';

  document.addEventListener('DOMContentLoaded', function () { boot(); });

  async function boot() {
    if (!window.$memberstackDom) return;
    var root = document.querySelector(ROOT_SELECTOR);
    if (!root) return;
    showListState(root, 'list-loading');

    var tableCourse = attr(root, 'ms-code-table-course', 'courses');
    var tableLesson = attr(root, 'ms-code-table-lesson', 'lessons');
    var tableProgress = attr(root, 'ms-code-table-progress', 'lesson_progress');
    var tableEnrollment = attr(root, 'ms-code-table-enrollment', 'enrollments');

    try {
      var ms = window.$memberstackDom;
      var member = await getMember(ms);
      if (!member || !member.id) {
        showListState(root, 'list-empty');
        return;
      }

      var loaded = await Promise.all([
        loadAll(ms, tableCourse, null),
        loadAll(ms, tableLesson, null),
        loadAll(ms, tableEnrollment, { owner: { equals: member.id } }),
        loadAll(ms, tableProgress, { owner: { equals: member.id } })
      ]);

      var courses = loaded[0] || [];
      var lessons = loaded[1] || [];
      var enrollments = loaded[2] || [];
      var progress = loaded[3] || [];

      var enrolledRows = buildEnrolledRows(courses, lessons, enrollments, progress);

      paintHeaderStats(root, enrolledRows);
      bindFilters(root, enrolledRows);
      paintGrid(root, enrolledRows);
      showListState(root, enrolledRows.length ? 'ready' : 'list-empty');
    } catch (err) {
      console.error('[enrolled-courses] boot failed', err);
      showListState(root, 'list-error');
    }
  }

  function buildEnrolledRows(courses, lessons, enrollments, progress) {
    var progressByCourse = Object.create(null);
    progress.forEach(function (p) {
      var cid = idOf(p.data && p.data.course);
      if (!cid) return;
      if (!progressByCourse[cid]) progressByCourse[cid] = [];
      progressByCourse[cid].push(p);
    });

    var lessonsByCourse = Object.create(null);
    lessons.forEach(function (l) {
      var cid = idOf(l.data && l.data.course);
      if (!cid) return;
      if (!lessonsByCourse[cid]) lessonsByCourse[cid] = [];
      lessonsByCourse[cid].push(l);
    });

    return enrollments
      .filter(function (e) {
        var s = normalize(e.data && e.data.status);
        return s !== 'dropped';
      })
      .map(function (e) {
        var cid = idOf(e.data && e.data.course);
        var course = byId(courses, cid);
        if (!course) return null;

        var courseLessons = lessonsByCourse[cid] || [];
        var courseProgress = progressByCourse[cid] || [];
        var completed = courseProgress.filter(function (p) {
          return Number(p.data && p.data.completed || 0) === 1;
        }).length;
        var total = courseLessons.length;
        var status = deriveStatus(completed, total, courseProgress.length);
        var pct = total > 0 ? Math.round((completed / total) * 100) : 0;

        return {
          enrollment: e,
          course: course,
          lessonsTotal: total,
          lessonsCompleted: completed,
          progressPercent: pct,
          status: status
        };
      })
      .filter(Boolean)
      .sort(function (a, b) {
        return Number(a.course.data && a.course.data.order || 0) - Number(b.course.data && b.course.data.order || 0);
      });
  }

  function deriveStatus(completed, total, started) {
    if (total > 0 && completed >= total) return 'complete';
    if (completed > 0 || started > 0) return 'in_progress';
    return 'not_started';
  }

  function paintHeaderStats(root, rows) {
    var totalCourses = rows.length;
    var totalLessons = rows.reduce(function (sum, r) { return sum + r.lessonsTotal; }, 0);
    var totalHours = rows.reduce(function (sum, r) {
      return sum + hoursFromEstimate(r.course.data && r.course.data.hours_estimate);
    }, 0);

    setText(root, '[data-ms-code="courses-count"]', totalCourses);
    setText(root, '[data-ms-code="lessons-count"]', totalLessons);
    setText(root, '[data-ms-code="hours-count"]', '~' + Math.round(totalHours));
  }

  function bindFilters(root, rows) {
    var bar = root.querySelector(FILTER_BAR_SELECTOR);
    if (!bar) return;
    var tpl = bar.querySelector(FILTER_TEMPLATE_SELECTOR);
    if (!tpl) return;

    clearClones(bar);
    tpl.style.display = 'none';

    var buckets = [
      { key: 'all', label: 'All', count: rows.length },
      { key: 'in_progress', label: 'In Progress', count: rows.filter(function (r) { return r.status === 'in_progress'; }).length },
      { key: 'complete', label: 'Completed', count: rows.filter(function (r) { return r.status === 'complete'; }).length }
    ];

    buckets.forEach(function (b, index) {
      var tab = tpl.cloneNode(true);
      tab.removeAttribute('data-ms-code');
      tab.setAttribute('data-ms-clone', 'true');
      tab.style.display = '';
      tab.setAttribute('data-filter', b.key);
      tab.setAttribute('data-filter-active', index === 0 ? 'true' : 'false');
      setText(tab, '[data-ms-code="filter-label"]', b.label);
      setText(tab, '[data-ms-code="filter-count"]', b.count);

      tab.addEventListener('click', function () {
        bar.querySelectorAll('[data-filter-active]').forEach(function (n) {
          n.setAttribute('data-filter-active', n === tab ? 'true' : 'false');
        });
        var filtered = b.key === 'all'
          ? rows
          : rows.filter(function (r) { return r.status === b.key; });
        paintGrid(root, filtered);
        showListState(root, filtered.length ? 'ready' : 'list-empty');
      });

      tpl.parentNode.insertBefore(tab, tpl);
    });
  }

  function paintGrid(root, rows) {
    var grid = root.querySelector(GRID_SELECTOR);
    if (!grid) return;
    var tpl = grid.querySelector(COURSE_TEMPLATE_SELECTOR);
    if (!tpl) return;

    clearClones(grid);
    tpl.style.display = 'none';

    if (!rows.length) return;

    rows.forEach(function (row) {
      var card = tpl.cloneNode(true);
      card.removeAttribute('data-ms-code');
      card.setAttribute('data-ms-clone', 'true');
      card.style.display = '';
      paintCard(card, row);
      tpl.parentNode.insertBefore(card, tpl);
    });
  }

  function paintCard(card, row) {
    var c = row.course.data || {};
    setText(card, '[data-ms-field="course.title"]', c.title);
    setText(card, '[data-ms-field="course.description"]', c.description);
    setText(card, '[data-ms-field="course.category"]', c.category);
    setText(card, '[data-ms-code="course-stats"]', row.lessonsTotal + ' LESSONS · ' + (c.hours_estimate || '~4 HOURS'));
    setText(card, '[data-ms-code="course-progress"]', row.lessonsCompleted + ' / ' + row.lessonsTotal + ' LESSONS');

    var fill = card.querySelector('[data-ms-code="course-progress-fill"]');
    if (fill) fill.style.width = row.progressPercent + '%';

    card.querySelectorAll('[data-ms-show-if="status"]').forEach(function (el) {
      var v = normalizeStatusValue(el.getAttribute('data-ms-show-value'));
      el.style.display = (v === row.status) ? '' : 'none';
      if (v === row.status) setText(el, '[data-ms-code="status-label"]', statusLabel(row.status));
    });

    var bg = card.querySelector('[data-ms-code="course-cover-bg"]');
    if (bg && c.cover_image) bg.style.backgroundImage = 'url("' + c.cover_image + '")';
    var img = card.querySelector('[data-ms-code="course-cover-img"]');
    if (img && img.tagName === 'IMG' && c.cover_image) img.setAttribute('src', c.cover_image);

    card.querySelectorAll('[data-ms-code="detail-link"]').forEach(function (a) {
      var page = a.getAttribute('ms-code-detail-page') || '';
      var param = a.getAttribute('ms-code-id-param') || 'id';
      if (!page) return;
      a.setAttribute('href', page + '?' + param + '=' + row.course.id);
    });
  }

  async function getMember(ms) {
    if (window.MSDataCache && typeof window.MSDataCache.getMember === 'function') {
      return window.MSDataCache.getMember(ms);
    }
    var result = await ms.getCurrentMember();
    return result && result.data ? result.data : null;
  }

  async function loadAll(ms, table, where) {
    if (window.MSDataCache && typeof window.MSDataCache.load === 'function') {
      return window.MSDataCache.load(ms, table, where || null);
    }
    return loadAllRaw(ms, table, where);
  }

  async function loadAllRaw(ms, table, where) {
    var all = [];
    var offset = 0;
    var limit = 100;
    var pageCount = 0;
    while (pageCount < 50) {
      var res = await ms.getData({
        dataTableId: table,
        where: where || undefined,
        limit: limit,
        offset: offset
      });
      var rows = res && res.data ? res.data : [];
      all = all.concat(rows);
      if (rows.length < limit) break;
      offset += limit;
      pageCount++;
    }
    return all;
  }

  function showListState(root, stateKey) {
    var loading = root.querySelector('[data-ms-code="list-loading"]');
    var empty = root.querySelector('[data-ms-code="list-empty"]');
    var error = root.querySelector('[data-ms-code="list-error"]');
    var showLoading = stateKey === 'list-loading';
    var showEmpty = stateKey === 'list-empty';
    var showError = stateKey === 'list-error';
    if (loading) loading.style.display = showLoading ? '' : 'none';
    if (empty) empty.style.display = showEmpty ? '' : 'none';
    if (error) error.style.display = showError ? '' : 'none';
  }

  function clearClones(root) {
    root.querySelectorAll('[data-ms-clone="true"]').forEach(function (n) {
      n.parentNode.removeChild(n);
    });
  }


  function attr(el, name, fallback) { return el.getAttribute(name) || fallback; }
  function idOf(ref) { return ref && (ref.id || ref) || null; }
  function byId(rows, id) { for (var i = 0; i < rows.length; i++) if (rows[i].id === id) return rows[i]; return null; }
  function normalize(v) { return String(v || '').trim().toLowerCase(); }
  function normalizeStatusValue(v) {
    var key = normalize(v).replace(/[\s-]+/g, '_');
    if (key === 'completed') return 'complete';
    return key;
  }
  function statusLabel(status) {
    if (status === 'complete') return 'Completed';
    if (status === 'in_progress') return 'In progress';
    return 'Not started';
  }
  function setText(root, sel, v) {
    if (v == null || v === '') return;
    var el = root.querySelector(sel);
    if (el) el.textContent = String(v);
  }

  function hoursFromEstimate(value) {
    if (value == null) return 0;
    var s = String(value);
    var match = s.match(/(\d+(\.\d+)?)/);
    return match ? Number(match[1]) : 0;
  }
})();

/* ===================== saved-courses.js ===================== */
(function () {
  'use strict';

  var LABEL = '[saved-courses]';
  var DEBUG = /[?&]debug\b/.test(window.location.search);
  var ROOT_SELECTOR = '[data-ms-code="saved-courses-page"]';
  var GRID_SELECTOR = '[data-ms-code="course-grid"]';
  var COURSE_TEMPLATE_SELECTOR = '[data-ms-code="course-template"]';
  var FILTER_BAR_SELECTOR = '[data-ms-code="filter-tabs"]';
  var FILTER_TEMPLATE_SELECTOR = '[data-ms-code="filter-tab-template"]';

  document.addEventListener('DOMContentLoaded', function () { boot(); });

  async function boot() {
    if (!window.$memberstackDom) return;
    var root = document.querySelector(ROOT_SELECTOR);
    if (!root) return;
    showListState(root, 'list-loading');

    var tableCourse = attr(root, 'ms-code-table-course', 'courses');
    var tableLesson = attr(root, 'ms-code-table-lesson', 'lessons');
    var tableProgress = attr(root, 'ms-code-table-progress', 'lesson_progress');
    var tableSaved = attr(root, 'ms-code-table-saved-courses', 'saved_courses');

    try {
      var ms = window.$memberstackDom;
      var member = await getMember(ms);
      if (!member || !member.id) {
        showListState(root, 'list-empty');
        return;
      }

      var loaded = await Promise.all([
        loadAll(ms, tableCourse, null),
        loadAll(ms, tableLesson, null),
        loadAll(ms, tableSaved, { owner: { equals: member.id } }),
        loadAll(ms, tableProgress, { owner: { equals: member.id } })
      ]);

      var courses = loaded[0] || [];
      var lessons = loaded[1] || [];
      var savedRows = loaded[2] || [];
      var progress = loaded[3] || [];

      var rows = buildSavedRows(courses, lessons, savedRows, progress);

      if (DEBUG) console.log(LABEL + ' loaded', {
        courses: courses.length, lessons: lessons.length,
        saved: savedRows.length, progress: progress.length,
        rows: rows.length
      });

      paintHeaderStats(root, rows);
      bindFilters(root, rows);
      paintGrid(root, rows);
      wireUnsaveButtons(root, ms, tableSaved);
      showListState(root, rows.length ? 'ready' : 'list-empty');
    } catch (err) {
      console.error(LABEL + ' boot failed', err);
      showListState(root, 'list-error');
    }
  }

  function buildSavedRows(courses, lessons, savedRows, progress) {
    var progressByCourse = Object.create(null);
    progress.forEach(function (p) {
      var cid = idOf(p.data && p.data.course);
      if (!cid) return;
      if (!progressByCourse[cid]) progressByCourse[cid] = [];
      progressByCourse[cid].push(p);
    });

    var lessonsByCourse = Object.create(null);
    lessons.forEach(function (l) {
      var cid = idOf(l.data && l.data.course);
      if (!cid) return;
      if (!lessonsByCourse[cid]) lessonsByCourse[cid] = [];
      lessonsByCourse[cid].push(l);
    });

    return savedRows
      .map(function (saved) {
        var cid = idOf(saved.data && saved.data.course);
        var course = byId(courses, cid);
        if (!course) return null;

        var courseLessons = lessonsByCourse[cid] || [];
        var courseProgress = progressByCourse[cid] || [];
        var completed = courseProgress.filter(function (p) {
          return Number(p.data && p.data.completed || 0) === 1;
        }).length;
        var total = courseLessons.length;
        var status = deriveStatus(completed, total, courseProgress.length);
        var pct = total > 0 ? Math.round((completed / total) * 100) : 0;

        return {
          saved: saved,
          course: course,
          lessonsTotal: total,
          lessonsCompleted: completed,
          progressPercent: pct,
          status: status
        };
      })
      .filter(Boolean)
      .sort(function (a, b) {
        return Number(a.course.data && a.course.data.order || 0) - Number(b.course.data && b.course.data.order || 0);
      });
  }

  function deriveStatus(completed, total, started) {
    if (total > 0 && completed >= total) return 'complete';
    if (completed > 0 || started > 0) return 'in_progress';
    return 'not_started';
  }

  function paintHeaderStats(root, rows) {
    var totalCourses = rows.length;
    var totalLessons = rows.reduce(function (sum, r) { return sum + r.lessonsTotal; }, 0);
    var totalHours = rows.reduce(function (sum, r) {
      return sum + hoursFromEstimate(r.course.data && r.course.data.hours_estimate);
    }, 0);

    setText(root, '[data-ms-code="courses-count"]', totalCourses);
    setText(root, '[data-ms-code="lessons-count"]', totalLessons);
    setText(root, '[data-ms-code="hours-count"]', '~' + Math.round(totalHours));
  }

  function bindFilters(root, rows) {
    var bar = root.querySelector(FILTER_BAR_SELECTOR);
    if (!bar) return;
    var tpl = bar.querySelector(FILTER_TEMPLATE_SELECTOR);
    if (!tpl) return;

    clearClones(bar);
    tpl.style.display = 'none';

    var buckets = [
      { key: 'all', label: 'All', count: rows.length },
      { key: 'in_progress', label: 'In Progress', count: rows.filter(function (r) { return r.status === 'in_progress'; }).length },
      { key: 'not_started', label: 'Not Started', count: rows.filter(function (r) { return r.status === 'not_started'; }).length },
      { key: 'complete', label: 'Completed', count: rows.filter(function (r) { return r.status === 'complete'; }).length }
    ];

    buckets.forEach(function (b, index) {
      var tab = tpl.cloneNode(true);
      tab.removeAttribute('data-ms-code');
      tab.setAttribute('data-ms-clone', 'true');
      tab.style.display = '';
      tab.setAttribute('data-filter', b.key);
      tab.setAttribute('data-filter-active', index === 0 ? 'true' : 'false');
      setText(tab, '[data-ms-code="filter-label"]', b.label);
      setText(tab, '[data-ms-code="filter-count"]', b.count);

      tab.addEventListener('click', function () {
        bar.querySelectorAll('[data-filter-active]').forEach(function (n) {
          n.setAttribute('data-filter-active', n === tab ? 'true' : 'false');
        });
        var filtered = b.key === 'all'
          ? rows
          : rows.filter(function (r) { return r.status === b.key; });
        paintGrid(root, filtered);
        showListState(root, filtered.length ? 'ready' : 'list-empty');
      });

      tpl.parentNode.insertBefore(tab, tpl);
    });
  }

  function paintGrid(root, rows) {
    var grid = root.querySelector(GRID_SELECTOR);
    if (!grid) return;
    var tpl = grid.querySelector(COURSE_TEMPLATE_SELECTOR);
    if (!tpl) return;

    clearClones(grid);
    tpl.style.display = 'none';
    if (!rows.length) return;

    rows.forEach(function (row) {
      var card = tpl.cloneNode(true);
      card.removeAttribute('data-ms-code');
      card.setAttribute('data-ms-clone', 'true');
      card.style.display = '';
      paintCard(card, row);
      tpl.parentNode.insertBefore(card, tpl);
    });
  }

  function paintCard(card, row) {
    var c = row.course.data || {};
    setText(card, '[data-ms-field="course.title"]', c.title);
    setText(card, '[data-ms-field="course.description"]', c.description);
    setText(card, '[data-ms-field="course.category"]', c.category);
    var hoursLabel = c.hours_estimate
      ? String(c.hours_estimate).toUpperCase()
      : ('~' + Math.round(row.lessonsTotal * 5 / 60) + ' HOURS');
    setText(card, '[data-ms-code="course-stats"]', row.lessonsTotal + ' LESSONS · ' + hoursLabel);

    card.querySelectorAll('[data-ms-show-if="status"]').forEach(function (el) {
      var v = normalizeStatusValue(el.getAttribute('data-ms-show-value'));
      el.style.display = (v === row.status) ? '' : 'none';
      if (v === row.status) setText(el, '[data-ms-code="status-label"]', statusLabel(row.status));
    });

    var fill = card.querySelector('[data-ms-code="course-progress-fill"]');
    if (fill) fill.style.width = row.progressPercent + '%';

    var bg = card.querySelector('[data-ms-code="course-cover-bg"]');
    if (bg && c.cover_image) bg.style.backgroundImage = 'url("' + c.cover_image + '")';
    var img = card.querySelector('[data-ms-code="course-cover-img"]');
    if (img && img.tagName === 'IMG' && c.cover_image) img.setAttribute('src', c.cover_image);

    card.querySelectorAll('[data-ms-code="detail-link"]').forEach(function (a) {
      var page = a.getAttribute('ms-code-detail-page') || '';
      var param = a.getAttribute('ms-code-id-param') || 'id';
      if (!page) return;
      a.setAttribute('href', page + '?' + param + '=' + row.course.id);
    });

    var savedId = recordId(row.saved);
    if (savedId) {
      card.querySelectorAll('[data-ms-action="delete"]').forEach(function (btn) {
        btn.setAttribute('data-ms-record-id', savedId);
      });
    }
  }

  function wireUnsaveButtons(root, ms, tableSaved) {
    root.addEventListener('click', function (e) {
      var btn = e.target.closest('[data-ms-action="delete"]');
      if (!btn) return;
      e.preventDefault();
      var rid = btn.getAttribute('data-ms-record-id');
      if (!rid) return;

      btn.setAttribute('disabled', 'true');
      btn.style.opacity = '0.5';

      writeWithRetry(function () { return ms.deleteDataRecord({ recordId: rid }); }, 'unsave-course')
        .then(function () {
          if (window.MSDataCache) window.MSDataCache.invalidate(tableSaved);
          window.location.reload();
        })
        .catch(function (err) {
          console.error(LABEL + ' unsave failed', err);
          btn.removeAttribute('disabled');
          btn.style.opacity = '';
        });
    });
  }

  function showListState(root, stateKey) {
    var loading = root.querySelector('[data-ms-code="list-loading"]');
    var empty = root.querySelector('[data-ms-code="list-empty"]');
    var error = root.querySelector('[data-ms-code="list-error"]');
    var showLoading = stateKey === 'list-loading';
    var showEmpty = stateKey === 'list-empty';
    var showError = stateKey === 'list-error';
    if (loading) loading.style.display = showLoading ? '' : 'none';
    if (empty) empty.style.display = showEmpty ? '' : 'none';
    if (error) error.style.display = showError ? '' : 'none';
  }

  async function getMember(ms) {
    if (window.MSDataCache && typeof window.MSDataCache.getMember === 'function') {
      return window.MSDataCache.getMember(ms);
    }
    var result = await ms.getCurrentMember();
    return result && result.data ? result.data : null;
  }

  async function loadAll(ms, table, where) {
    if (window.MSDataCache && typeof window.MSDataCache.load === 'function') {
      return window.MSDataCache.load(ms, table, where || null);
    }
    return loadAllRaw(ms, table, where);
  }

  async function loadAllRaw(ms, table, where) {
    var all = [];
    var offset = 0;
    var limit = 100;
    var pageCount = 0;
    while (pageCount < 50) {
      var res = await ms.getData({
        dataTableId: table,
        where: where || undefined,
        limit: limit,
        offset: offset
      });
      var rows = res && res.data ? res.data : [];
      all = all.concat(rows);
      if (rows.length < limit) break;
      offset += limit;
      pageCount++;
    }
    return all;
  }

  function clearClones(root) {
    root.querySelectorAll('[data-ms-clone="true"]').forEach(function (n) {
      n.parentNode.removeChild(n);
    });
  }


  function attr(el, name, fallback) { return el.getAttribute(name) || fallback; }

  function idOf(ref) {
    if (!ref) return null;
    if (typeof ref === 'string') return ref;
    if (Array.isArray(ref)) return idOf(ref[0]);
    if (typeof ref === 'object') return ref.id || ref._id || null;
    return null;
  }

  function recordId(r) {
    if (!r) return null;
    return r.id || r._id || r.recordId || null;
  }

  // Run a single write through MSDataCache.runWrites so it inherits 429
  // backoff + retry. Falls back to a plain call if runWrites is unavailable.
  function writeWithRetry(thunk, label) {
    if (window.MSDataCache && typeof window.MSDataCache.runWrites === 'function') {
      return window.MSDataCache.runWrites([thunk], { label: label, stopOnError: true })
        .then(function (o) { return o.results[0]; });
    }
    return Promise.resolve().then(thunk);
  }

  function byId(rows, id) { for (var i = 0; i < rows.length; i++) if (rows[i].id === id) return rows[i]; return null; }
  function normalize(v) { return String(v || '').trim().toLowerCase(); }
  function normalizeStatusValue(v) {
    var key = normalize(v).replace(/[\s-]+/g, '_');
    if (key === 'completed') return 'complete';
    return key;
  }
  function statusLabel(status) {
    if (status === 'complete') return 'Completed';
    if (status === 'in_progress') return 'In progress';
    return 'Not started';
  }
  function setText(root, sel, v) {
    if (v == null || v === '') return;
    var el = root.querySelector(sel);
    if (el) el.textContent = String(v);
  }

  function hoursFromEstimate(value) {
    if (value == null) return 0;
    var s = String(value);
    var match = s.match(/(\d+(\.\d+)?)/);
    return match ? Number(match[1]) : 0;
  }
})();

/* ===================== nav-courses.js ===================== */
(function () {
  'use strict';

  var ROOT_SELECTOR = '[data-ms-code="nav-courses"]';
  var TEMPLATE_SELECTOR = '[data-ms-code="list-template"]';

  document.addEventListener('DOMContentLoaded', function () { boot(); });

  async function boot() {
    if (!window.$memberstackDom) return;

    var root = document.querySelector(ROOT_SELECTOR);
    if (!root) return;

    var table = root.getAttribute('ms-code-table') || 'courses';
    var perPage = parseInt(root.getAttribute('ms-code-per-page'), 10) || 0;

    try {
      var ms = window.$memberstackDom;
      var courses = await loadAll(ms, table);
      courses.sort(byOrderAsc);
      if (perPage > 0) courses = courses.slice(0, perPage);
      paintGrid(root, courses);
    } catch (err) {
      console.error('[nav-courses] boot failed', err);
    }
  }

  async function loadAll(ms, table) {
    if (window.MSDataCache && typeof window.MSDataCache.load === 'function') {
      return window.MSDataCache.load(ms, table, null);
    }
    var all = [];
    var offset = 0;
    var limit = 100;
    while (true) {
      var res = await ms.getData({ dataTableId: table, limit: limit, offset: offset });
      var rows = res && res.data ? res.data : [];
      all = all.concat(rows);
      if (rows.length < limit) break;
      offset += limit;
    }
    return all;
  }

  function paintGrid(root, courses) {
    var tpl = root.querySelector(TEMPLATE_SELECTOR);
    if (!tpl) return;

    clearClones(root);
    tpl.style.display = 'none';

    courses.forEach(function (course) {
      var card = tpl.cloneNode(true);
      card.removeAttribute('data-ms-code');
      card.setAttribute('data-ms-clone', 'true');
      card.style.display = '';

      var d = course.data || {};

      var img = card.querySelector('[data-ms-field="cover_image"]');
      if (img && d.cover_image) img.setAttribute('src', d.cover_image);

      setText(card, '[data-ms-field="title"]', d.title);
      setText(card, '[data-ms-field="description"]', d.description);
      setText(card, '[data-ms-field="category"]', d.category);
      setText(card, '[data-ms-code="lesson-count"]', formatCount(d.lesson_count, 'Lesson'));
      setText(card, '[data-ms-code="hours-estimate"]', formatHours(d.hours_estimate));

      var page = tpl.getAttribute('ms-code-detail-page') || '/course';
      var param = tpl.getAttribute('ms-code-id-param') || 'id';
      card.setAttribute('href', page + '?' + param + '=' + course.id);

      root.insertBefore(card, tpl);
    });
  }

  function formatCount(n, label) {
    var num = parseInt(n, 10) || 0;
    return num + ' ' + label + (num === 1 ? '' : 's');
  }

  function formatHours(val) {
    if (!val) return '';
    var n = parseFloat(val);
    if (isNaN(n)) return val;
    return n + ' Hour' + (n === 1 ? '' : 's');
  }

  function setText(root, sel, value) {
    if (value == null || value === '') return;
    var el = root.querySelector(sel);
    if (el) el.textContent = String(value);
  }

  function clearClones(root) {
    root.querySelectorAll('[data-ms-clone="true"]').forEach(function (n) { n.remove(); });
  }

  function byOrderAsc(a, b) {
    return (Number(a.data && a.data.order || 0)) - (Number(b.data && b.data.order || 0));
  }
})();
